files.godcode/ast.py:
"""Abstract syntax tree nodes for God Code v2.0.

Every node carries 1-based ``line``/``col`` of the token that opened it.
Expression fields are annotated with the ``Expr`` alias (a union of all
expression node types).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Union

# Filled in below once the classes exist; string form keeps runtime cheap.
Expr = Union[
    "BinaryOp", "UnaryOp", "Literal", "Identifier",
    "ListLiteral", "Index", "CallExpr",
]


# -- program structure -------------------------------------------------------

@dataclass
class Program:
    statements: list = field(default_factory=list)
    line: int = 1
    col: int = 1


@dataclass
class CreationBlock:
    statements: list = field(default_factory=list)
    line: int = 1
    col: int = 1


# -- statements --------------------------------------------------------------

@dataclass
class Declare:
    name: str
    value: Expr
    line: int = 1
    col: int = 1


@dataclass
class DeclareIntent:
    """DECLARE INTENT "words..." ON rite_name -- the v4.0 intent layer."""
    text: str
    rite: str
    line: int = 1
    col: int = 1


@dataclass
class DeclarePermission:
    """DECLARE PERMISSION TO <power> -- the permission manifest.

    ``power`` is one of "read", "write", "network", "stdin", "summon";
    ``target`` is the granted path, host, or verb name (None for stdin).
    """
    power: str
    target: str | None
    line: int = 1
    col: int = 1


@dataclass
class Breathe:
    name: str
    line: int = 1
    col: int = 1


@dataclass
class Reveal:
    expr: Expr
    line: int = 1
    col: int = 1


@dataclass
class Prophesy:
    text: str
    line: int = 1
    col: int = 1


@dataclass
class Ascend:
    line: int = 1
    col: int = 1


@dataclass
class Reflect:
    line: int = 1
    col: int = 1


@dataclass
class Bless:
    name: str
    line: int = 1
    col: int = 1


@dataclass
class Anoint:
    name: str
    line: int = 1
    col: int = 1


@dataclass
class SealStmt:
    expr: Expr
    line: int = 1
    col: int = 1


@dataclass
class Testify:
    expr: Expr
    line: int = 1
    col: int = 1


@dataclass
class IfStmt:
    cond: Expr
    then_body: list = field(default_factory=list)
    else_body: list = field(default_factory=list)
    has_else: bool = False  # True when an ELSE keyword was actually written
    line: int = 1
    col: int = 1


@dataclass
class ForLoop:
    var: str
    iterable: Expr
    body: list = field(default_factory=list)
    line: int = 1
    col: int = 1


@dataclass
class WhileLoop:
    cond: Expr
    body: list = field(default_factory=list)
    line: int = 1
    col: int = 1


@dataclass
class Break:
    """BREAK: release the innermost enclosing loop at once."""
    line: int = 1
    col: int = 1


@dataclass
class Continue:
    """CONTINUE: skip to the next turn of the innermost enclosing loop."""
    line: int = 1
    col: int = 1


@dataclass
class TryStmt:
    """TRY ... CATCH [name] ... ENDTRY: in-language error handling.

    The TRY block runs first; if a runtime error (GodRuntimeError) rises,
    the error's plain message is bound to ``error_name`` and the CATCH
    block runs. ``error_name`` defaults to "ERROR" when the CATCH carries
    no name. Control-flow signals (RETURN, ASCEND) are never caught.
    """
    try_body: list = field(default_factory=list)
    catch_body: list = field(default_factory=list)
    error_name: str = "ERROR"
    line: int = 1
    col: int = 1


@dataclass
class DefineRite:
    name: str
    params: list = field(default_factory=list)  # list[str]
    body: list = field(default_factory=list)
    line: int = 1
    col: int = 1


@dataclass
class Return:
    expr: Expr | None = None
    line: int = 1
    col: int = 1


@dataclass
class Import:
    path: str
    line: int = 1
    col: int = 1


@dataclass
class ExprStmt:
    expr: Expr
    line: int = 1
    col: int = 1


# -- expressions -------------------------------------------------------------

@dataclass
class BinaryOp:
    # op: '+','-','*','/','%', '==','!=','<','>','<=','>=', 'and','or'
    op: str
    left: Expr
    right: Expr
    line: int = 1
    col: int = 1


@dataclass
class UnaryOp:
    # op: 'not', '-'
    op: str
    operand: Expr
    line: int = 1
    col: int = 1


@dataclass
class Literal:
    value: object  # int | float | str | bool | None
    line: int = 1
    col: int = 1


@dataclass
class InterpolatedString:
    """A string holding ``{expr}`` blessings: parts are literal text (str)
    or expression nodes whose revealed value is breathed into the string.
    ``source`` keeps the original string content so formatters can re-emit it.
    """

    parts: list = field(default_factory=list)  # list[str | Expr]
    source: str = ""
    line: int = 1
    col: int = 1


@dataclass
class Identifier:
    name: str
    line: int = 1
    col: int = 1


@dataclass
class ListLiteral:
    items: list = field(default_factory=list)  # list[Expr]
    line: int = 1
    col: int = 1


@dataclass
class Index:
    obj: Expr
    index: Expr
    line: int = 1
    col: int = 1


@dataclass
class CallExpr:
    callee: str
    args: list = field(default_factory=list)  # list[Expr]
    line: int = 1
    col: int = 1

files.godcode/chain.py:
"""Blockchain-anchored seals for God Code v4.0 -- "Intent & Chain".

A ChainAdapter anchors a payload hash into a tamper-evident chain and
later verifies the receipt it handed back. The bundled
SimulatedChainAdapter keeps the anchor chain as local JSONL
(``anchors.chain``), mirroring :class:`godcode.ledger.CovenantLedger`;
real chain adapters (Ethereum, and the like) can be registered later
with :func:`register_adapter` -- that work belongs to the founder, not
to this module. There are no network calls here, no wallets, no keys.
"""

from __future__ import annotations

import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path

GENESIS_PREV_HASH = "GENESIS"
DEFAULT_CHAIN_NAME = "simulated"


def _canonical(payload: dict) -> bytes:
    """Canonical JSON bytes used for hashing (stable key order, no whitespace)."""
    return json.dumps(payload, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=False).encode("utf-8")


def _block_hash(index: int, timestamp: str, record: dict, prev_hash: str) -> str:
    return hashlib.sha256(
        _canonical(
            {"index": index, "timestamp": timestamp,
             "record": record, "prev_hash": prev_hash}
        )
    ).hexdigest()


class ChainAdapter:
    """The contract every chain adapter honors.

    ``anchor(payload_hash)`` writes the hash into the chain and returns a
    receipt dict; ``verify(receipt)`` returns True only when the receipt
    matches a block that is still intact.
    """

    name = "adapter"

    def anchor(self, payload_hash: str) -> dict:
        raise NotImplementedError

    def verify(self, receipt: dict) -> bool:
        raise NotImplementedError


class SimulatedChainAdapter(ChainAdapter):
    """A local tamper-evident anchor chain (JSONL), standing in for a chain.

    Blocks look like ``{index, timestamp, record: {payload_hash},
    prev_hash, hash}``; the chain begins at ``"GENESIS"``. Receipts look
    like ``{chain, anchor_hash, height, timestamp, payload_hash}``.
    """

    name = "simulated"

    def __init__(self, path: str | Path | None = "anchors.chain") -> None:
        self.path = Path(path) if path is not None else None
        self._memory: list[dict] = []
        if self.path is not None and str(self.path.parent) not in ("", "."):
            self.path.parent.mkdir(parents=True, exist_ok=True)

    # ---------------------------------------------------------- persistence

    def read_all(self) -> list[dict]:
        """Every anchor block in chain order (empty when no chain yet)."""
        if self.path is None:
            return list(self._memory)
        if not self.path.exists():
            return []
        blocks: list[dict] = []
        with open(self.path, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line:
                    blocks.append(json.loads(line))
        return blocks

    def _append(self, block: dict) -> None:
        if self.path is None:
            self._memory.append(block)
        else:
            with open(self.path, "a", encoding="utf-8") as f:
                f.write(json.dumps(block, ensure_ascii=False) + "\n")

    # ------------------------------------------------------------- adapter

    def anchor(self, payload_hash: str) -> dict:
        """Anchor a payload hash; return the receipt dict."""
        blocks = self.read_all()
        index = len(blocks)
        prev_hash = blocks[-1]["hash"] if blocks else GENESIS_PREV_HASH
        timestamp = datetime.now(timezone.utc).isoformat()
        record = {"payload_hash": payload_hash}
        block = {
            "index": index,
            "timestamp": timestamp,
            "record": record,
            "prev_hash": prev_hash,
            "hash": _block_hash(index, timestamp, record, prev_hash),
        }
        self._append(block)
        return {
            "chain": self.name,
            "anchor_hash": block["hash"],
            "height": block["index"],
            "timestamp": block["timestamp"],
            "payload_hash": payload_hash,
        }

    def verify(self, receipt: dict) -> bool:
        """True when the receipt names a block that is present and intact."""
        try:
            height = receipt["height"]
            anchor_hash = receipt["anchor_hash"]
            payload_hash = receipt["payload_hash"]
        except (KeyError, TypeError, AttributeError):
            return False
        if not isinstance(height, int) or isinstance(height, bool):
            return False
        blocks = self.read_all()
        if height < 0 or height >= len(blocks):
            return False
        block = blocks[height]
        if block.get("hash") != anchor_hash:
            return False
        if block.get("record", {}).get("payload_hash") != payload_hash:
            return False
        return _block_hash(
            block.get("index"),
            block.get("timestamp"),
            block.get("record"),
            block.get("prev_hash"),
        ) == block.get("hash")

    def verify_chain(self) -> tuple[bool, str]:
        """Recompute the whole anchor chain.

        (True, 'N anchors intact') or (False, 'anchor chain broken at
        block K').
        """
        blocks = self.read_all()
        prev_hash = GENESIS_PREV_HASH
        for expected, block in enumerate(blocks):
            payload_ok = (
                block.get("index") == expected
                and block.get("prev_hash") == prev_hash
                and _block_hash(
                    block.get("index"),
                    block.get("timestamp"),
                    block.get("record"),
                    block.get("prev_hash"),
                )
                == block.get("hash")
            )
            if not payload_ok:
                return False, f"anchor chain broken at block {block.get('index')} ⚓💔"
            prev_hash = block["hash"]
        return True, f"{len(blocks)} anchors intact ⚓"


class MemoryChainAdapter(SimulatedChainAdapter):
    """An ephemeral in-memory anchor chain: the sandbox's answer to ANCHOR.

    Same interface as the simulated chain, but nothing is written to
    disk. Anchors made here vanish when the run ends -- which is exactly
    what a deny-by-default sandbox requires.
    """

    name = "simulated"

    def __init__(self) -> None:
        super().__init__(path=None)


# ------------------------------------------------------------- registry

_ADAPTERS: dict[str, ChainAdapter] = {}


def register_adapter(name: str, adapter: ChainAdapter) -> None:
    """Register a chain adapter under *name* (e.g. a future real chain)."""
    if not isinstance(name, str) or not name:
        raise ValueError("a chain adapter needs a non-empty string name")
    if not isinstance(adapter, ChainAdapter):
        raise ValueError(f"'{name}' is not a ChainAdapter")
    _ADAPTERS[name] = adapter


def get_adapter(name: str) -> ChainAdapter | None:
    """The adapter registered under *name*, or None."""
    return _ADAPTERS.get(name)


def default_adapters() -> dict[str, ChainAdapter]:
    """A fresh per-interpreter registry holding the bundled adapters."""
    adapters = dict(_ADAPTERS)
    adapters.setdefault(DEFAULT_CHAIN_NAME, SimulatedChainAdapter())
    return adapters


register_adapter(DEFAULT_CHAIN_NAME, SimulatedChainAdapter())

files.godcode/cli.py:
"""Command-line interface for the God Code engine.

Subcommands: run, check, repl, fmt, ledger verify.
Sibling modules (lexer, parser, ast, interpreter, ledger, errors) are imported
lazily inside each command so `--help` works even before they land.
"""
from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path


# ---------------------------------------------------------------------------
# run
# ---------------------------------------------------------------------------
def _print_run_error(source: str, err) -> None:
    """Print a failed run's error the gentle way, then the call trace.

    The gentle rendering (message, line/col, source line, caret,
    Did-you-mean) is preserved exactly; the trace goes underneath in plain
    words. Errors raised at the top level carry an empty trace and show no
    trace section.
    """
    from godcode.errors import format_call_trace, format_error

    print(format_error(source, err), file=sys.stderr)
    trace = list(getattr(err, "call_trace", None) or [])
    for line in format_call_trace(trace):
        print(line, file=sys.stderr)


# --- v3: agentics --json ---
def _make_interpreter(log_path):
    """Build an Interpreter the way `godcode run` always has, shared by the
    plain and --json run paths so they can never drift apart."""
    from godcode.interpreter import Interpreter

    kwargs: dict = {}
    if log_path:
        kwargs["log_path"] = log_path
    # Bind the Spirit and the covenant ledger by default; degrade
    # gracefully if either cannot be raised in this environment.
    try:
        from godcode.spirit import SpiritEngine
        kwargs["spirit"] = SpiritEngine()
    except Exception:
        pass
    try:
        from godcode.ledger import CovenantLedger
        kwargs["ledger"] = CovenantLedger()
    except Exception:
        pass
    return Interpreter(**kwargs)
# --- end v3: agentics --json ---


def cmd_run(args: argparse.Namespace) -> int:
    from godcode.errors import GodCodeError

    # --- v3: sandbox commands ---
    if getattr(args, "sandbox", False):
        return _cmd_run_sandboxed(args)
    # --- end v3: sandbox commands ---

    # --- v3: agentics --json ---
    if getattr(args, "json", False):
        from godcode import agentics
        return agentics.cmd_run_json(args)
    # --- end v3: agentics --json ---

    try:
        source = Path(args.file).read_text(encoding="utf-8")
    except OSError as exc:
        print(f"godcode: cannot read '{args.file}': {exc.strerror or exc}",
              file=sys.stderr)
        return 1

    try:
        _make_interpreter(args.log).run_source(source, source_name=args.file)
    except GodCodeError as err:
        _print_run_error(source, err)
        return 1
    return 0


# --- v3: sandbox commands ---
def _cmd_run_sandboxed(args: argparse.Namespace) -> int:
    """Run a scroll under the strict sandbox policy.

    Spirit, covenant ledger, and the audit log stay unbound: they write
    to the host world, which the sandbox does not permit. The CLI itself
    reads the scroll file before the sandbox is entered — that read is
    the invoker's own act, not the creation's.
    """
    from godcode.errors import GodCodeError
    from godcode.sandbox import SandboxPolicy, run_sandboxed

    try:
        source = Path(args.file).read_text(encoding="utf-8")
    except OSError as exc:
        if getattr(args, "json", False):
            from godcode import agentics
            agentics.emit(agentics.run_payload(
                args.file, False, [], [],
                agentics._file_error_diagnostic(args.file, exc), 0))
        else:
            print(f"godcode: cannot read '{args.file}': {exc.strerror or exc}",
                  file=sys.stderr)
        return 1

    source_dir = str(Path(args.file).resolve().parent)
    policy = SandboxPolicy.strict(
        source_dir=source_dir,
        timeout_seconds=args.sandbox_timeout,
    )
    if getattr(args, "json", False):
        # Machine-readable report; stdout carries exactly one JSON document.
        import contextlib
        import io
        import time as _time

        from godcode import agentics
        from godcode.sandbox import run_sandboxed_with_interpreter

        error = None
        output: list[str] = []
        intents: list[dict] = []
        interp = None
        start = _time.perf_counter()
        with contextlib.redirect_stdout(io.StringIO()):
            try:
                output, interp = run_sandboxed_with_interpreter(
                    source, policy, source_name=args.file)
                intents = list(getattr(interp, "intent_checks", []) or [])
            except GodCodeError as err:
                error = agentics.diagnostic(err)
                error["trace"] = agentics.error_trace(err)
        ms = int((_time.perf_counter() - start) * 1000)
        manifest = getattr(interp, "manifest", None)
        agentics.emit(agentics.run_payload(
            args.file, error is None, output, [], error, ms,
            intents=intents,
            permissions=manifest.to_json() if manifest else {}))
        return 0 if error is None else 1
    try:
        run_sandboxed(source, policy, source_name=args.file)
    except GodCodeError as err:
        _print_run_error(source, err)
        return 1
    return 0
# --- end v3: sandbox commands ---


# ---------------------------------------------------------------------------
# check
# ---------------------------------------------------------------------------
def cmd_check(args: argparse.Namespace) -> int:
    from godcode.errors import GodCodeError, format_error
    from godcode.tongues import parse_source

    # --- v3: agentics --json ---
    if getattr(args, "json", False):
        from godcode import agentics
        return agentics.cmd_check_json(args)
    # --- end v3: agentics --json ---

    try:
        source = Path(args.file).read_text(encoding="utf-8")
    except OSError as exc:
        print(f"godcode: cannot read '{args.file}': {exc.strerror or exc}",
              file=sys.stderr)
        return 1
    try:
        parse_source(source)
    except GodCodeError as err:
        print(format_error(source, err), file=sys.stderr)
        return 1
    print(f"✓ {args.file} is pure.")
    return 0


# ---------------------------------------------------------------------------
# lint
# ---------------------------------------------------------------------------
def cmd_lint(args: argparse.Namespace) -> int:
    import json as _json

    from godcode.errors import GodCodeError, format_error
    from godcode.linter import lint_source

    try:
        source = Path(args.file).read_text(encoding="utf-8")
    except OSError as exc:
        print(f"godcode: cannot read '{args.file}': {exc.strerror or exc}",
              file=sys.stderr)
        return 1
    try:
        findings = lint_source(source, source_name=args.file)
    except GodCodeError as err:
        print(format_error(source, err), file=sys.stderr)
        return 1

    if getattr(args, "json", False):
        print(_json.dumps(
            {"tool": "godcode", "command": "lint", "file": args.file,
             "ok": not findings,
             "findings": [{"line": f.line, "col": f.col, "rule": f.rule,
                           "message": f.message} for f in findings]},
            ensure_ascii=False))
        return 1 if findings else 0
    for f in findings:
        print(f"line {f.line}, col {f.col} [{f.rule}] {f.message}")
    return 1 if findings else 0


# ---------------------------------------------------------------------------
# test — the test runner
# ---------------------------------------------------------------------------
def cmd_test(args: argparse.Namespace) -> int:
    import json as _json

    from godcode import tester

    target = Path(args.dir)
    if not target.is_dir():
        print(f"godcode: '{args.dir}' is not a directory to test.",
              file=sys.stderr)
        return 2
    report = tester.run_tests(target)
    if getattr(args, "json", False):
        print(_json.dumps(report.payload(args.dir), ensure_ascii=False))
    else:
        for line in report.text_lines():
            print(line)
    return 1 if report.failed else 0


# ---------------------------------------------------------------------------
# new — raise a fresh God Code project
# ---------------------------------------------------------------------------
def cmd_new(args: argparse.Namespace) -> int:
    import json as _json

    from godcode.scaffold import ScaffoldError, create_project

    try:
        result = create_project(args.name, dest=args.path, author=args.author)
    except ScaffoldError as exc:
        if getattr(args, "json", False):
            print(_json.dumps({"tool": "godcode", "command": "new",
                               "ok": False, "error": str(exc)},
                              ensure_ascii=False))
        else:
            print(f"godcode: {exc}", file=sys.stderr)
        return 1
    if getattr(args, "json", False):
        print(_json.dumps({
            "tool": "godcode", "command": "new", "ok": True,
            "name": result.name,
            "directory": str(result.directory),
            "files": result.files,
        }, ensure_ascii=False))
        return 0
    print(f"🕊 A new scroll rises: {result.directory}")
    for filename in result.files:
        print(f"  wrote {result.directory / filename}")
    print("")
    print("Next steps:")
    print(f"  cd {result.directory}")
    print("  godcode run main.god   # speak it")
    print("  godcode test .         # test it")
    return 0


# ---------------------------------------------------------------------------
# repl
# ---------------------------------------------------------------------------
def cmd_repl(args: argparse.Namespace) -> int:  # noqa: ARG001
    from godcode.errors import GodCodeError, format_error
    from godcode.interpreter import Interpreter

    try:
        import readline  # noqa: F401  (enables history + line editing)
    except ImportError:
        pass

    print("God Code Live Mode 🕊")
    print("Speak your creation; end each utterance with a blank line. "
          "(:quit to ascend)")
    interp = Interpreter(interactive=True)
    buf: list[str] = []
    while True:
        try:
            line = input("godcode> " if not buf else "...... ")
        except EOFError:
            print()
            break
        except KeyboardInterrupt:
            print()
            break
        if line.strip() in (":quit", ":q"):
            break
        if not line.strip():
            if buf:
                chunk = "\n".join(buf)
                buf = []
                try:
                    interp.run_source(chunk, source_name="<repl>")
                except GodCodeError as err:
                    print(str(err), file=sys.stderr)
            continue
        buf.append(line)
    print("🕊 The sanctuary rests.")
    return 0


# ---------------------------------------------------------------------------
# fmt — AST -> canonical God Code
# ---------------------------------------------------------------------------
_PRECEDENCE = {
    "or": 1, "and": 2,
    "==": 3, "!=": 3, "<": 3, ">": 3, "<=": 3, ">=": 3,
    "+": 4, "-": 4, "*": 5, "/": 5, "%": 5,
}
_UNARY_PREC = 6
_BLOCK_NODES = {"CreationBlock", "IfStmt", "ForLoop", "WhileLoop",
               "DefineRite", "TryStmt"}


def _escape(text: str) -> str:
    return (text.replace("\\", "\\\\").replace('"', '\\"')
                .replace("\n", "\\n").replace("\t", "\\t"))


class CanonicalFormatter:
    """Re-emit an AST as canonical God Code: keywords UPPER, 2-space indent,
    one statement per line, blank line between top-level blocks."""

    def __init__(self) -> None:
        self._lines: list[str] = []
        self._depth = 0

    # -- driver ---------------------------------------------------------
    def format(self, program) -> str:
        prev_was_block = False
        for i, stmt in enumerate(program.statements):
            is_block = type(stmt).__name__ in _BLOCK_NODES
            if i and (is_block or prev_was_block):
                self._lines.append("")
            self._emit_stmt(stmt)
            prev_was_block = is_block
        return "\n".join(self._lines) + "\n"

    def _emit_stmt(self, node) -> None:
        meth = getattr(self, "_stmt_" + type(node).__name__, None)
        if meth is None:
            raise ValueError(
                f"the formatter knows not this node: {type(node).__name__}")
        meth(node)

    def _line(self, text: str) -> None:
        self._lines.append("  " * self._depth + text)

    def _block(self, stmts) -> None:
        self._depth += 1
        for stmt in stmts:
            self._emit_stmt(stmt)
        self._depth -= 1

    # -- expressions ----------------------------------------------------
    def _expr(self, node, parent_prec: int = 0) -> str:
        kind = type(node).__name__
        if kind == "BinaryOp":
            prec = _PRECEDENCE[node.op]
            op = node.op.upper() if node.op in ("and", "or") else node.op
            text = (f"{self._expr(node.left, prec)} {op} "
                    f"{self._expr(node.right, prec + 1)}")
            return f"({text})" if prec < parent_prec else text
        if kind == "UnaryOp":
            inner = self._expr(node.operand, _UNARY_PREC)
            if type(node.operand).__name__ == "UnaryOp":
                inner = f"({inner})"
            return f"NOT {inner}" if node.op == "not" else f"-{inner}"
        if kind == "Literal":
            return self._literal(node.value)
        if kind == "InterpolatedString":
            return f'"{_escape(node.source)}"'
        if kind == "Identifier":
            return node.name
        if kind == "ListLiteral":
            return "[" + ", ".join(self._expr(i) for i in node.items) + "]"
        if kind == "Index":
            return f"{self._expr(node.obj, _UNARY_PREC)}[{self._expr(node.index)}]"
        if kind == "CallExpr":
            return (f"{node.callee}("
                    + ", ".join(self._expr(a) for a in node.args) + ")")
        raise ValueError(
            f"the formatter knows not this expression: {kind}")

    @staticmethod
    def _literal(value) -> str:
        if isinstance(value, str):
            return f'"{_escape(value)}"'
        if value is True:
            return "true"
        if value is False:
            return "false"
        if value is None:
            return "void"
        return repr(value)

    # -- statements -----------------------------------------------------
    def _stmt_CreationBlock(self, node) -> None:
        self._line("BEGIN CREATION")
        self._block(node.statements)
        self._line("END CREATION")

    def _stmt_Declare(self, node) -> None:
        value = node.value
        if type(value).__name__ == "ListLiteral":
            rhs = ", ".join(self._expr(i) for i in value.items)
        else:
            rhs = self._expr(value)
        self._line(f"DECLARE {node.name} AS {rhs}")

    def _stmt_DeclareIntent(self, node) -> None:  # v4.0
        self._line(f'DECLARE INTENT "{_escape(node.text)}" ON {node.rite}')

    def _stmt_DeclarePermission(self, node) -> None:
        power = node.power.upper()
        if power == "READ":
            self._line(f'DECLARE PERMISSION TO READ "{_escape(node.target)}"')
        elif power == "WRITE":
            self._line(f'DECLARE PERMISSION TO WRITE "{_escape(node.target)}"')
        elif power == "NETWORK":
            self._line(f'DECLARE PERMISSION TO SPEAK WITH "{_escape(node.target)}"')
        elif power == "STDIN":
            self._line("DECLARE PERMISSION TO ASK THE WORLD")
        elif power == "SUMMON":
            self._line(f'DECLARE PERMISSION TO SUMMON "{_escape(node.target)}"')

    def _stmt_Breathe(self, node) -> None:
        self._line(f"BREATHE LIFE INTO {node.name}")

    def _stmt_Reveal(self, node) -> None:
        self._line(f"REVEAL({self._expr(node.expr)})")

    def _stmt_Prophesy(self, node) -> None:
        self._line(f"PROPHESY {node.text}".rstrip())

    def _stmt_Ascend(self, node) -> None:
        self._line("ASCEND")

    def _stmt_Reflect(self, node) -> None:
        self._line("REFLECT")

    def _stmt_Bless(self, node) -> None:
        self._line(f"BLESS {node.name}")

    def _stmt_Anoint(self, node) -> None:
        self._line(f"ANOINT {node.name}")

    def _stmt_SealStmt(self, node) -> None:
        self._line(f"SEAL {self._expr(node.expr)}")

    def _stmt_Testify(self, node) -> None:
        self._line(f"TESTIFY {self._expr(node.expr)}")

    def _stmt_IfStmt(self, node) -> None:
        self._line(f"IF {self._expr(node.cond)} THEN")
        self._block(node.then_body)
        if node.else_body:
            self._line("ELSE")
            self._block(node.else_body)
        self._line("ENDIF")

    def _stmt_ForLoop(self, node) -> None:
        self._line(f"FOR {node.var} IN {self._expr(node.iterable)}")
        self._block(node.body)
        self._line("ENDFOR")

    def _stmt_WhileLoop(self, node) -> None:
        self._line(f"WHILE {self._expr(node.cond)} DO")
        self._block(node.body)
        self._line("ENDWHILE")

    def _stmt_TryStmt(self, node) -> None:
        self._line("TRY")
        self._block(node.try_body)
        if node.error_name == "ERROR":
            self._line("CATCH")
        else:
            self._line(f"CATCH {node.error_name}")
        self._block(node.catch_body)
        self._line("ENDTRY")

    def _stmt_DefineRite(self, node) -> None:
        params = ", ".join(node.params)
        self._line(f"DEFINE RITE {node.name}({params})")
        self._block(node.body)
        self._line("END RITE")

    def _stmt_Return(self, node) -> None:
        self._line("RETURN" if node.expr is None
                   else f"RETURN {self._expr(node.expr)}")

    def _stmt_Break(self, node) -> None:
        self._line("BREAK")

    def _stmt_Continue(self, node) -> None:
        self._line("CONTINUE")

    def _stmt_Import(self, node) -> None:
        self._line(f'IMPORT "{_escape(node.path)}"')

    def _stmt_ExprStmt(self, node) -> None:
        expr = node.expr
        if type(expr).__name__ == "CallExpr":
            args = ", ".join(self._expr(a) for a in expr.args)
            self._line(f"INVOKE {expr.callee}({args})")
        else:
            self._line(self._expr(expr))


def cmd_fmt(args: argparse.Namespace) -> int:
    from godcode.errors import GodCodeError, format_error
    from godcode.tongues import parse_source

    src_path = Path(args.file)
    try:
        source = src_path.read_text(encoding="utf-8")
    except OSError as exc:
        print(f"godcode: cannot read '{args.file}': {exc.strerror or exc}",
              file=sys.stderr)
        return 1
    try:
        program = parse_source(source)
    except GodCodeError as err:
        print(format_error(source, err), file=sys.stderr)
        return 1

    canonical = CanonicalFormatter().format(program)
    if args.in_place:
        src_path.write_text(canonical, encoding="utf-8")
    else:
        sys.stdout.write(canonical)
    return 0


