# ---------------------------------------------------------------------------
# parser assembly
# ---------------------------------------------------------------------------
def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="godcode",
        description="God Code. The language of divine computation 🕊")
    sub = parser.add_subparsers(dest="command", required=True)

    p_run = sub.add_parser("run", help="Execute a God Code scroll")
    p_run.add_argument("file", help="Path to the .god scroll")
    p_run.add_argument("--log", default=None, metavar="PATH",
                       help="Audit log path (default: logs/godcode.log)")
    # --- v3: sandbox commands ---
    p_run.add_argument("--sandbox", action="store_true",
                       help="Run under the strict sandbox policy "
                            "(deny fs writes, network, subprocesses, "
                            "stdin; scroll imports limited to the "
                            "scroll's own directory and the stdlib "
                            "scrolls; time and step budgets enforced)")
    p_run.add_argument("--sandbox-timeout", type=float, default=5.0,
                       metavar="SECS",
                       help="Wall-clock grant for --sandbox runs "
                            "(default: 5.0 seconds)")
    # --- end v3: sandbox commands ---
    # --- v3: agentics --json ---
    p_run.add_argument("--json", action="store_true",
                       help="Emit a machine-readable JSON report on stdout")
    # --- end v3: agentics --json ---
    p_run.set_defaults(func=cmd_run)

    p_check = sub.add_parser("check",
                             help="Lex and parse a scroll without running it")
    p_check.add_argument("file", help="Path to the .god scroll")
    # --- v3: agentics --json ---
    p_check.add_argument("--json", action="store_true",
                         help="Emit a machine-readable JSON report on stdout")
    # --- end v3: agentics --json ---
    p_check.set_defaults(func=cmd_check)

    p_repl = sub.add_parser("repl", help="Enter the live sanctuary")
    p_repl.set_defaults(func=cmd_repl)

    p_fmt = sub.add_parser("fmt", help="Re-emit a scroll in canonical form")
    p_fmt.add_argument("file", help="Path to the .god scroll")
    p_fmt.add_argument("--in-place", "-w", dest="in_place",
                       action="store_true",
                       help="Rewrite the file instead of printing")
    p_fmt.set_defaults(func=cmd_fmt)

    p_lint = sub.add_parser("lint",
                            help="Lint a scroll for unused names, shadowing, "
                                 "empty blocks, and other quiet troubles")
    p_lint.add_argument("file", help="Path to the .god scroll")
    p_lint.add_argument("--json", action="store_true",
                        help="Emit a machine-readable JSON report on stdout")
    p_lint.set_defaults(func=cmd_lint)

    p_test = sub.add_parser(
        "test",
        help="Run the TEST_ rites in a directory's test scrolls")
    p_test.add_argument("dir", nargs="?", default=".",
                        help="Directory holding test scrolls (default: the "
                             "current directory). Only that directory is "
                             "read; subfolders are not entered.")
    p_test.add_argument("--json", action="store_true",
                        help="Emit a machine-readable JSON report on stdout")
    p_test.set_defaults(func=cmd_test)

    p_new = sub.add_parser(
        "new",
        help="Raise a new God Code project (starter scroll, test scroll, "
             "scroll manifest, README)")
    p_new.add_argument("name", help="Project name (lowercase, e.g. my-scroll)")
    p_new.add_argument("--path", default=".", metavar="DIR",
                       help="Parent directory for the new project "
                            "(default: the current directory)")
    p_new.add_argument("--author", default="",
                       help="Author name for the scroll manifest")
    p_new.add_argument("--json", action="store_true",
                       help="Emit a machine-readable JSON report on stdout")
    p_new.set_defaults(func=cmd_new)

    p_ledger = sub.add_parser("ledger", help="Covenant ledger commands")
    ledger_sub = p_ledger.add_subparsers(dest="ledger_command", required=True)
    p_verify = ledger_sub.add_parser("verify",
                                     help="Verify the covenant chain")
    p_verify.add_argument("--file", default="covenant.chain", metavar="PATH",
                          help="Chain file (default: covenant.chain)")
    # --- v4.0: the anchor chain is verified alongside the covenant chain ---
    p_verify.add_argument("--anchor-file", default="anchors.chain",
                          metavar="PATH",
                          help="Anchor chain file (default: anchors.chain)")
    # --- end v4.0 ---
    p_verify.set_defaults(func=cmd_ledger_verify)

    # --- v4.0: intent, tools, bridge commands ---
    p_intent = sub.add_parser("intent",
                              help="Resolve the intent behind words "
                                   "with the Spirit Engine")
    p_intent.add_argument("text", help="Words to resolve the intent of")
    p_intent.add_argument("--json", action="store_true",
                          help="Emit a machine-readable JSON report on stdout")
    p_intent.set_defaults(func=cmd_intent)

    p_permissions = sub.add_parser("permissions",
                                   help="Read a scroll's permission manifest "
                                        "without running it")
    p_permissions.add_argument("file", help="The .god scroll to read")
    p_permissions.add_argument("--json", action="store_true",
                               help="Emit a machine-readable JSON report "
                                    "on stdout")
    p_permissions.set_defaults(func=cmd_permissions)

    p_tools = sub.add_parser("tools",
                             help="Show the MCP-compatible agent tool schemas")
    p_tools.add_argument("--json", action="store_true",
                         help="Emit the schemas as JSON")
    p_tools.set_defaults(func=cmd_tools)

    p_bridge = sub.add_parser("bridge",
                              help="Serve the agent tool bridge "
                                   "(JSON-RPC 2.0 over stdio)")
    p_bridge.set_defaults(func=cmd_bridge)
    # --- end v4.0 ---

    # --- v3: scroll commands ---
    _add_scroll_commands(sub)
    # --- end v3: scroll commands ---

    # --- v3: lsp commands ---
    p_lsp = sub.add_parser("lsp",
                           help="Start the language server over stdio")
    p_lsp.set_defaults(func=cmd_lsp)
    # --- end v3: lsp commands ---

    # --- v5.0: dap commands ---
    p_dap = sub.add_parser("dap",
                           help="Start the God Code debug adapter (DAP) "
                                "over stdio")
    p_dap.set_defaults(func=cmd_dap)
    # --- end v5.0: dap commands ---

    # --- v5.0: interactive debugger ---
    p_debug = sub.add_parser("debug",
                             help="Debug a God Code scroll interactively")
    p_debug.add_argument("file", help="Path to the .god scroll")
    p_debug.add_argument("--break", "-b", dest="breaks", action="append",
                         type=int, default=[], metavar="LINE",
                         help="Pause at LINE as well as on entry "
                              "(repeatable)")
    p_debug.set_defaults(func=cmd_debug)
    # --- end v5.0 ---

    return parser


def main(argv=None) -> int:
    """Entry point. Returns 0 on success; raises SystemExit(code) on failure."""
    args = build_parser().parse_args(argv)
    code = args.func(args)
    if code:
        raise SystemExit(code)
    return 0


if __name__ == "__main__":
    sys.exit(main())

files.godcode/dap.py:
"""Debug Adapter Protocol server for God Code (v5.0).

A minimal DAP implementation over stdio, hand-rolled on top of the stdlib.
Messages are framed with ``Content-Length`` headers, exactly like
:mod:`godcode.lsp`.

Lifecycle::

    godcode dap                       # start serving on stdin/stdout

The message loop runs on the main thread. ``launch`` builds an interpreter
the same way ``godcode run`` does, attaches a
:class:`godcode.debugger.DebugSession`, and starts the scroll on a daemon
worker thread. Pauses surface as ``stopped`` events; the worker thread
blocks inside the session until a ``continue`` / ``next`` / ``stepIn`` /
``stepOut`` request resumes it.

Protocol notes:
  * All logging goes to stderr. stdout is the protocol channel. Nothing
    else may ever be written there (REVEAL output is forwarded as DAP
    ``output`` events instead).
  * Unknown commands answer with JSON-RPC error -32601 ("Method not found").
  * Malformed frames are skipped; the server keeps serving.
"""

from __future__ import annotations

import io
import json
import os
import re
import sys
import threading

from godcode.debugger import DebugSession
from godcode.errors import GodCodeError

# A handler that already sent its own response returns this, so the
# dispatcher does not answer twice (used by launch and disconnect).
_HANDLED = object()

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*$")

_CAPABILITIES = {
    "supportsConfigurationDoneRequest": True,
    "supportsEvaluateForHovers": False,
}


def _log(message: str) -> None:
    sys.stderr.write(f"[godcode-dap] {message}\n")
    sys.stderr.flush()


class DebugAdapter:
    """Hand-rolled DAP server over stdio."""

    def __init__(self,
                 stdin: io.BufferedReader | None = None,
                 stdout: io.BufferedWriter | None = None) -> None:
        self.stdin = stdin or sys.stdin.buffer
        self.stdout = stdout or sys.stdout.buffer
        self._write_lock = threading.Lock()
        self._seq = 0
        self._session: DebugSession | None = None
        self._worker: threading.Thread | None = None
        self._pending_breakpoints: dict[str, set[int]] = {}
        # Variable references: id -> ("frame_locals", frame_id)
        #                   or ("value", python_value). Allocated from 1.
        self._var_refs: dict[int, tuple] = {}
        self._next_var_ref = 1
        self._handlers = {
            "initialize": self._on_initialize,
            "launch": self._on_launch,
            "configurationDone": self._on_configuration_done,
            "setBreakpoints": self._on_set_breakpoints,
            "threads": self._on_threads,
            "stackTrace": self._on_stack_trace,
            "scopes": self._on_scopes,
            "variables": self._on_variables,
            "evaluate": self._on_evaluate,
            "continue": self._on_continue,
            "next": self._on_next,
            "stepIn": self._on_step_in,
            "stepOut": self._on_step_out,
            "disconnect": self._on_disconnect,
        }

    # ------------------------------------------------------------ transport
    def _read_message(self) -> dict | None:
        """Read one Content-Length framed message. None on clean EOF."""
        headers: dict[str, str] = {}
        while True:
            line = self.stdin.readline()
            if not line:
                return None  # EOF
            line = line.decode("latin-1").strip()
            if not line:
                break
            if ":" in line:
                name, _, value = line.partition(":")
                headers[name.strip().lower()] = value.strip()
        try:
            length = int(headers.get("content-length", ""))
        except (TypeError, ValueError):
            _log("malformed frame: bad Content-Length; skipping")
            return {}
        try:
            body = self._read_exact(length)
        except EOFError:
            _log("malformed frame: truncated body; skipping")
            return {}
        try:
            return json.loads(body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            _log(f"malformed frame: {exc}; skipping")
            return {}

    def _read_exact(self, length: int) -> bytes:
        body = b""
        while len(body) < length:
            chunk = self.stdin.read(length - len(body))
            if not chunk:
                raise EOFError("truncated frame")
            body += chunk
        return body

    def _next_seq(self) -> int:
        with self._write_lock:
            self._seq += 1
            return self._seq

    def _write(self, payload: dict) -> None:
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        frame = (f"Content-Length: {len(body)}\r\n\r\n".encode("ascii")
                 + body)
        with self._write_lock:
            self.stdout.write(frame)
            self.stdout.flush()

    def _send_response(self, request_seq, command: str,
                       success: bool = True,
                       body: dict | None = None,
                       message: str = "") -> None:
        payload: dict = {
            "seq": self._next_seq(),
            "type": "response",
            "request_seq": request_seq,
            "success": success,
            "command": command,
        }
        if success:
            if body is not None:
                payload["body"] = body
        elif message:
            payload["message"] = message
        self._write(payload)

    def _send_event(self, event: str, body: dict | None = None) -> None:
        payload: dict = {
            "seq": self._next_seq(),
            "type": "event",
            "event": event,
        }
        if body is not None:
            payload["body"] = body
        self._write(payload)

    def _send_jsonrpc_error(self, msg_id, code: int,
                            message: str) -> None:
        self._write({"jsonrpc": "2.0", "id": msg_id,
                     "error": {"code": code, "message": message}})

    def _send_output(self, text: str, category: str = "stdout") -> None:
        if not text.endswith("\n"):
            text += "\n"
        self._send_event("output",
                         {"category": category, "output": text})

    # ------------------------------------------------------------ main loop
    def serve(self) -> int:
        _log("the debug adapter opens (stdio)")
        while True:
            message = self._read_message()
            if message is None:
                _log("stdin closed; ascending")
                return 0
            if not message:
                continue  # malformed frame: already logged, keep serving
            self._dispatch(message)

    def _dispatch(self, message: dict) -> None:
        command = message.get("command") or message.get("method")
        seq = message.get("seq", message.get("id"))
        if not command:
            _log("message with no command; ignoring")
            return
        handler = self._handlers.get(command)
        if handler is None:
            _log(f"unknown command: {command!r}")
            if seq is not None:
                self._send_jsonrpc_error(seq, -32601,
                                         f"Method not found: {command}")
            return
        args = message.get("arguments") or message.get("params") or {}
        try:
            result = handler(seq, command, args)
        except Exception as exc:  # never let a handler kill the server
            _log(f"handler for {command} failed: {exc}")
            if seq is not None:
                self._send_response(seq, command, success=False,
                                    message=str(exc))
            return
        if result is _HANDLED or seq is None:
            return
        self._send_response(seq, command, success=True, body=result)

    # ------------------------------------------------------ session helpers
    def _require_session(self) -> DebugSession:
        if self._session is None:
            raise RuntimeError("no program is launched")
        return self._session

    def _frames_innermost_first(self) -> list:
        session = self._session
        if session is None:
            return []
        return list(reversed(session.frames))

    def _frame_by_id(self, frame_id: int):
        frames = self._frames_innermost_first()
        if 0 <= frame_id < len(frames):
            return frames[frame_id]
        return None

    def _alloc_var_ref(self, entry: tuple) -> int:
        ref = self._next_var_ref
        self._next_var_ref += 1
        self._var_refs[ref] = entry
        return ref

    @staticmethod
    def _children_of(value) -> list[tuple[str, object]]:
        if isinstance(value, list):
            return [(str(i), item) for i, item in enumerate(value)]
        if isinstance(value, dict):
            return [(str(key), item) for key, item in value.items()]
        return []

    def _variable(self, name: str, value) -> dict:
        session = self._require_session()
        ref = 0
        if isinstance(value, (list, dict)):
            ref = self._alloc_var_ref(("value", value))
        return {
            "name": str(name),
            "value": session.render_value(value),
            "type": session.type_name(value),
            "variablesReference": ref,
        }

    # -------------------------------------------------------------- handlers
    def _on_initialize(self, seq, command, args: dict):  # noqa: ARG002
        _log("initialize received")
        result = {"capabilities": dict(_CAPABILITIES)}
        # Respond first so the client sees a clean handshake ordering.
        self._send_response(seq, command, success=True, body=result)
        self._send_event("initialized")
        return _HANDLED

    def _on_launch(self, seq, command, args: dict):
        if self._session is not None:
            raise RuntimeError("a program is already launched")
        program = args.get("program")
        if not program:
            raise RuntimeError("launch requires a 'program' path")
        stop_on_entry = args.get("stopOnEntry", True)
        _log(f"launch: {program} (stopOnEntry={stop_on_entry})")

        from godcode.cli import _make_interpreter

        interpreter = _make_interpreter(None)
        session = DebugSession()
        for path, lines in self._pending_breakpoints.items():
            for line in sorted(lines):
                session.add_breakpoint(path, line)
        self._pending_breakpoints.clear()

        original_emit = interpreter.emit

        def _emit(line: str, _orig=original_emit) -> None:
            _orig(line)  # printed, as `godcode run` does
            self._send_output(str(line), category="stdout")

        interpreter.emit = _emit
        session.on_pause = self._on_pause
        session.attach(interpreter)
        session.stop_on_entry = bool(stop_on_entry)
        self._session = session

        # Answer before the worker starts, so the client never sees a
        # stopped event ahead of the launch response.
        self._send_response(seq, command, success=True, body={})
        worker = threading.Thread(
            target=self._run_program,
            args=(session, str(program)),
            daemon=True,
            name="godcode-dap-worker",
        )
        self._worker = worker
        worker.start()
        return _HANDLED

    def _run_program(self, session: DebugSession, program: str) -> None:
        try:
            session.run_file(program)
        except GodCodeError as err:
            _log(f"program error: {err}")
            self._send_output(str(err), category="stderr")
            self._send_event("terminated")
            return
        except Exception as err:  # noqa: BLE001 - never die silently
            _log(f"worker failed: {err}")
            self._send_output(f"{type(err).__name__}: {err}",
                              category="stderr")
            self._send_event("terminated")
            return
        _log("program finished")
        self._send_event("terminated")
        self._send_event("exited", {"exitCode": 0})

    def _on_pause(self, pause_info: dict) -> None:
        reason = pause_info.get("reason", "pause")
        line = pause_info.get("line")
        source = pause_info.get("source")
        _log(f"paused: {reason} at {source}:{line}")
        # The session blocks inside _pause until a request handler calls
        # session.resume(); this handler only announces the stop.
        self._send_event("stopped", {
            "reason": reason,
            "threadId": 1,
            "allThreadsStopped": True,
        })

    def _on_configuration_done(self, seq, command,  # noqa: ARG002
                               args: dict):  # noqa: ARG002
        _log("configuration done")
        return {}

    def _on_set_breakpoints(self, seq, command, args: dict):  # noqa: ARG002
        source = args.get("source") or {}
        path = source.get("path", "")
        lines: list[int] = []
        for bp in args.get("breakpoints") or []:
            line = (bp or {}).get("line")
            if isinstance(line, int):
                lines.append(line)
        if self._session is not None:
            self._session.clear_breakpoints(path)
            for line in lines:
                self._session.add_breakpoint(path, line)
        else:
            # Arrived before launch; applied when the session is created.
            self._pending_breakpoints[path] = set(lines)
        norm = DebugSession._norm(path) if path else ""
        _log(f"breakpoints for {norm or path}: {lines}")
        return {"breakpoints": [
            {"verified": True, "line": n,
             "source": {"name": os.path.basename(norm) if norm else "",
                        "path": norm}}
            for n in lines
        ]}

    def _on_threads(self, seq, command, args: dict):  # noqa: ARG002
        return {"threads": [{"id": 1, "name": "creation"}]}

    def _on_stack_trace(self, seq, command, args: dict):  # noqa: ARG002
        out = []
        for i, frame in enumerate(self._frames_innermost_first()):
            src = frame.source or ""
            out.append({
                "id": i,
                "name": frame.name,
                "line": frame.line or 1,
                "column": 1,
                "source": {
                    "name": os.path.basename(src) if src else "scroll",
                    "path": src,
                },
            })
        return {"stackFrames": out, "totalFrames": len(out)}

    def _on_scopes(self, seq, command, args: dict):  # noqa: ARG002
        frame_id = args.get("frameId", 0)
        ref = self._alloc_var_ref(("frame_locals", frame_id))
        return {"scopes": [
            {"name": "Locals", "variablesReference": ref,
             "expensive": False}
        ]}

    def _on_variables(self, seq, command, args: dict):  # noqa: ARG002
        entry = self._var_refs.get(args.get("variablesReference", 0))
        pairs: list[tuple[str, object]] = []
        if entry is not None:
            if entry[0] == "frame_locals":
                frame = self._frame_by_id(entry[1])
                if frame is not None:
                    pairs = self._require_session().frame_locals(frame)
            elif entry[0] == "value":
                pairs = self._children_of(entry[1])
        return {"variables": [self._variable(name, value)
                              for name, value in pairs[:50]]}

    def _on_evaluate(self, seq, command, args: dict):  # noqa: ARG002
        session = self._require_session()
        expr = str(args.get("expression", "")).strip()
        frame = self._frame_by_id(args.get("frameId", 0))
        name = expr if _IDENT_RE.match(expr) else None
        if name is not None:
            found, value = session.lookup(name, frame)
            if found:
                return {
                    "result": session.render_value(value),
                    "type": session.type_name(value),
                    "variablesReference": 0,
                }
        return {"result": f"no '{expr}' is bound here.",
                "variablesReference": 0}

    def _on_continue(self, seq, command, args: dict):  # noqa: ARG002
        self._require_session().resume("continue")
        return {"allThreadsContinued": True}

    def _on_next(self, seq, command, args: dict):  # noqa: ARG002
        self._require_session().resume("step_over")
        return {"allThreadsContinued": True}

    def _on_step_in(self, seq, command, args: dict):  # noqa: ARG002
        self._require_session().resume("step_in")
        return {"allThreadsContinued": True}

    def _on_step_out(self, seq, command, args: dict):  # noqa: ARG002
        self._require_session().resume("step_out")
        return {"allThreadsContinued": True}

    def _on_disconnect(self, seq, command, args: dict):  # noqa: ARG002
        self._send_response(seq, command, success=True, body={})
        _log("disconnect; ascending")
        os._exit(0)


def serve() -> int:
    """Entry point for ``godcode dap``."""
    return DebugAdapter().serve()

files.godcode/debugger.py:
"""Interactive debugging for God Code (v5.0).

A :class:`DebugSession` plugs into the interpreter through the small hook
surface on ``Interpreter`` (``interpreter.debugger``):

* ``before_stmt(stmt, env)`` — called before every statement executes.
* ``enter_rite(rite, env)`` / ``exit_rite(rite)`` — around rite bodies.
* ``enter_file(path)`` / ``exit_file()`` — around imported scrolls.

When a pause condition is met (breakpoint, step, or stop-on-entry) the
session calls ``on_pause(pause_info)`` and blocks until the driver calls
``resume(action)``. The CLI driver answers inline; the DAP driver answers
from its message loop while the program runs on a worker thread.

Hook contract for driver authors::

    session = DebugSession()
    session.on_pause = my_handler          # must call session.resume(action)
    session.add_breakpoint("/path/scroll.god", 12)
    session.attach(interpreter)            # sets interpreter.debugger
    session.stop_on_entry = True           # pause at the first statement
    session.run_file("/path/scroll.god")   # lex, parse, run, manage sources

Resume actions: ``"continue"``, ``"step_in"``, ``"step_over"``,
``"step_out"``.
"""

from __future__ import annotations

import threading
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable

RESUME_ACTIONS = ("continue", "step_in", "step_over", "step_out")

_PAUSE_BREAKPOINT = "breakpoint"
_PAUSE_STEP = "step"
_PAUSE_ENTRY = "entry"


@dataclass
class DebugFrame:
    """One frame of the paused call stack."""

    name: str  # rite name, or "<creation>" for the top level
    env: Any = None  # godcode.environment.Environment
    stmt: Any = None  # statement about to execute (or None)
    source: str = ""
    depth: int = 0

    @property
    def line(self) -> int | None:
        return getattr(self.stmt, "line", None)


class DebugSession:
    """Drives a paused/stepped run of a God Code program."""

    def __init__(self) -> None:
        self.breakpoints: dict[str, set[int]] = {}
        self.frames: list[DebugFrame] = []
        self.on_pause: Callable[[dict], None] | None = None
        self.stop_on_entry = False
        self.interpreter = None
        # stepping state
        self._step_mode = "run"  # run | step_in | step_over | step_out
        self._step_depth = 0
        self._pause_once = False
        # sources
        self._source_stack: list[str] = []
        # pause machinery
        self._resume_event = threading.Event()
        self._resume_event.set()
        self.resume_action = "continue"
        self.pause_info: dict | None = None
        self.pause_count = 0
        self.finished = False
        self.error: Any = None

    # ------------------------------------------------------------ breakpoints

    @staticmethod
    def _norm(source: str) -> str:
        try:
            return str(Path(source).resolve())
        except OSError:
            return str(source)

    def add_breakpoint(self, source: str, line: int) -> None:
        self.breakpoints.setdefault(self._norm(source), set()).add(int(line))

    def remove_breakpoint(self, source: str, line: int) -> None:
        self.breakpoints.get(self._norm(source), set()).discard(int(line))

    def clear_breakpoints(self, source: str | None = None) -> None:
        if source is None:
            self.breakpoints.clear()
        else:
            self.breakpoints.pop(self._norm(source), None)

    def breakpoints_for(self, source: str) -> set[int]:
        return set(self.breakpoints.get(self._norm(source), set()))

    # ----------------------------------------------------------------- sources

    @property
    def current_source(self) -> str:
        return self._source_stack[-1] if self._source_stack else ""

    def push_source(self, source: str) -> None:
        self._source_stack.append(self._norm(source))

    def pop_source(self) -> None:
        if self._source_stack:
            self._source_stack.pop()

    # ------------------------------------------------------------------ attach

    def attach(self, interpreter) -> "DebugSession":
        """Plug this session into an interpreter's hook surface."""
        self.interpreter = interpreter
        interpreter.debugger = self
        return self

    def detach(self) -> None:
        if self.interpreter is not None:
            self.interpreter.debugger = None
        self.interpreter = None

    # --------------------------------------------------------------------- run

    def run_file(self, path: str | Path):
        """Lex, parse, and run a scroll under this session.

        Returns the interpreter. Runtime errors propagate to the caller;
        ``self.error`` records them and ``self.finished`` is set either way.
        """
        from godcode.tongues import parse_source

        if self.interpreter is None:
            raise RuntimeError("DebugSession has no interpreter. Call attach() first.")
        resolved = str(Path(path).resolve())
        source = Path(path).read_text(encoding="utf-8")
        program = parse_source(source)
        if self.stop_on_entry:
            self._pause_once = True
        self.push_source(resolved)
        try:
            self.interpreter.run(program, source_name=resolved)
        except Exception as err:  # noqa: BLE001 - recorded for the driver
            self.error = err
            raise
        finally:
            self.pop_source()
            self.finished = True
        return self.interpreter

    # ---------------------------------------------------------- interpreter hooks

    @property
    def depth(self) -> int:
        return len(self.frames)

    def _current_frame(self, env) -> DebugFrame:
        if not self.frames:
            self.frames.append(
                DebugFrame(name="<creation>", env=env,
                           source=self.current_source, depth=1)
            )
        frame = self.frames[-1]
        frame.env = env
        return frame

    def before_stmt(self, stmt, env) -> None:
        frame = self._current_frame(env)
        frame.stmt = stmt
        reason = self._pause_reason(stmt)
        if reason is not None:
            self._pause(reason, stmt, frame)

    def enter_rite(self, rite, env) -> None:
        self.frames.append(
            DebugFrame(name=getattr(rite, "name", "<rite>"), env=env,
                       source=self.current_source,
                       depth=len(self.frames) + 1)
        )

    def exit_rite(self, rite) -> None:
        if self.frames:
            self.frames.pop()
        # step_out lands on the next statement back in the caller.
        if self._step_mode == "step_out" and len(self.frames) < self._step_depth:
            self._step_mode = "step_over"
            self._step_depth = len(self.frames)
            self._pause_once = True

    def enter_file(self, path: str) -> None:
        self.push_source(path)

    def exit_file(self) -> None:
        self.pop_source()

    # ------------------------------------------------------------------ pausing

    def _pause_reason(self, stmt) -> str | None:
        if self._pause_once:
            self._pause_once = False
            return _PAUSE_ENTRY if self.pause_count == 0 else _PAUSE_STEP
        if self._step_mode == "step_in":
            return _PAUSE_STEP
        if self._step_mode == "step_over" and len(self.frames) <= self._step_depth:
            return _PAUSE_STEP
        if self._step_mode == "run":
            line = getattr(stmt, "line", None)
            if line is not None and line in self.breakpoints.get(self.current_source, ()):
                return _PAUSE_BREAKPOINT
        return None

    def _pause(self, reason: str, stmt, frame: DebugFrame) -> None:
        self.pause_count += 1
        self.pause_info = {
            "reason": reason,
            "stmt": stmt,
            "frame": frame,
            "frames": list(self.frames),
            "source": self.current_source,
            "line": getattr(stmt, "line", None),
            "pause_count": self.pause_count,
        }
        self._resume_event.clear()
        try:
            if self.on_pause is not None:
                self.on_pause(self.pause_info)
            else:  # no driver: behave like "continue" so runs never hang
                self.resume("continue")
        finally:
            self._resume_event.wait()
        self._apply_resume()

    def resume(self, action: str) -> None:
        """Answer a pause. Safe to call from any thread."""
        if action not in RESUME_ACTIONS:
            raise ValueError(f"unknown resume action: {action!r}")
        self.resume_action = action
        self._resume_event.set()

    def _apply_resume(self) -> None:
        action = self.resume_action
        if action == "continue":
            self._step_mode = "run"
        elif action == "step_in":
            self._step_mode = "step_in"
        elif action == "step_over":
            self._step_mode = "step_over"
            self._step_depth = len(self.frames)
        elif action == "step_out":
            self._step_mode = "step_out"
            self._step_depth = len(self.frames)

    # --------------------------------------------------------------- inspection

    def render_value(self, value) -> str:
        if self.interpreter is not None:
            return self.interpreter.stringify(value)
        return str(value)

    def type_name(self, value) -> str:
        if self.interpreter is not None:
            return self.interpreter.type_name(value)
        return type(value).__name__

    def frame_locals(self, frame: DebugFrame) -> list[tuple[str, Any]]:
        """(name, value) pairs visible in a frame, innermost first."""
        if frame.env is None:
            return []
        try:
            return list(frame.env.items())
        except Exception:  # noqa: BLE001 - defensive; never break a pause
            return []

    def lookup(self, name: str, frame: DebugFrame | None = None):
        """Resolve a name in a frame's environment. Returns (found, value)."""
        frame = frame or (self.frames[-1] if self.frames else None)
        if frame is None or frame.env is None:
            return False, None
        env = frame.env
        while env is not None:
            bindings = getattr(env, "_bindings", {})
            if name in bindings:
                return True, bindings[name]
            env = getattr(env, "parent", None)
        return False, None

    def source_lines(self, source: str | None = None) -> list[str]:
        """Source lines of a file for context display (1-based indexing)."""
        path = source or self.current_source
        try:
            return Path(path).read_text(encoding="utf-8").splitlines()
        except OSError:
            return []

