"""Recursive-descent parser for God Code v2.0.

``Parser(tokens).parse()`` returns a ``Program``. A program is either a
``BEGIN CREATION ... END CREATION`` block (wrapped in a Program) or a
bare sequence of statements (for scrolls / fragments).

Statement forms (spec §4):
- DECLARE name AS expr (, expr)*      -> Declare (multi-expr -> ListLiteral)
- BREATHE LIFE INTO name              -> Breathe
- REVEAL(expr)                        -> Reveal
- PROPHESY <rest of line>             -> Prophesy
- ASCEND / REFLECT                    -> Ascend / Reflect
- BLESS name / ANOINT name            -> Bless / Anoint
- SEAL expr / TESTIFY expr            -> SealStmt / Testify
- IF expr THEN ... (block: ENDIF / inline)          -> IfStmt
- FOR name IN expr ... (block: ENDFOR / legacy open / inline) -> ForLoop
- WHILE expr DO ... (block: ENDWHILE / inline)      -> WhileLoop
- TRY ... CATCH [name] ... ENDTRY (block)           -> TryStmt
- DEFINE RITE name(params) ... END RITE (block or inline) -> DefineRite
- RETURN expr?                        -> Return
- IMPORT "path"                       -> Import
- INVOKE name(args) | any expression   -> CallExpr / ExprStmt

Expression precedence (low -> high):
  or -> and -> not -> comparison (IS [NOT], =, ==, !=, <, >, <=, >=)
  -> additive (+ -) -> multiplicative (* / %) -> unary (-, NOT) -> primary
``IS``/``IS NOT`` become ``==``/``!=`` BinaryOps.
"""

from __future__ import annotations

from . import ast as A
from .errors import ParseError
from .lexer import Lexer
from .tokens import Token, TokenType

TT = TokenType

_EXPR_STARTS = {
    TT.NUMBER, TT.STRING, TT.IDENT, TT.LPAREN, TT.LBRACKET,
    TT.MINUS, TT.NOT, TT.TRUE, TT.FALSE, TT.VOID, TT.INVOKE,
}

# Tokens after which RETURN takes no expression.
_RETURN_TERMINATORS = {
    TT.NEWLINE, TT.EOF, TT.END, TT.ENDIF, TT.ELSE, TT.ENDFOR, TT.ENDWHILE,
    TT.CATCH, TT.ENDTRY,
}


class Parser:
    def __init__(self, tokens: list[Token], tongue: str | None = None):
        if not tokens:
            raise ParseError("The scroll is empty; there is nothing to reveal")
        self.tokens = tokens
        self.pos = 0
        # The tongue the source was lexed in ("en" when none); carried into
        # interpolated {expressions} so their keywords speak it too.
        self._tongue = tongue or "en"
        # Tracks lexically enclosing FOR/WHILE loops so BREAK and CONTINUE
        # can be rejected at parse time when no loop holds them. A rite
        # body resets this to 0: loop signals never cross a rite boundary.
        self._loop_depth = 0

    # -- public ------------------------------------------------------------

    def parse(self) -> A.Program:
        self._skip_newlines()
        first = self._peek()
        if self._check(TT.BEGIN):
            block = self._parse_creation_block()
            self._skip_newlines()
            t = self._peek()
            if t.type is not TT.EOF:
                raise ParseError(
                    f"The creation is sealed, yet {self._describe(t)} remains; "
                    "a scroll holds only one creation",
                    line=t.line, col=t.col,
                )
            return A.Program(statements=[block], line=block.line, col=block.col)
        stmts = self._parse_body(
            end={TT.EOF},
            missing="the end of the scroll",
            opening=None,
        )
        return A.Program(statements=stmts, line=first.line, col=first.col)

    # -- cursor helpers ----------------------------------------------------

    def _peek(self) -> Token:
        return self.tokens[self.pos]

    def _peek_next(self) -> Token:
        if self.pos + 1 < len(self.tokens):
            return self.tokens[self.pos + 1]
        return self.tokens[-1]

    def _advance(self) -> Token:
        t = self.tokens[self.pos]
        if self.pos < len(self.tokens) - 1:
            self.pos += 1
        return t

    def _check(self, tt: TokenType) -> bool:
        return self._peek().type is tt

    def _expect(self, tt: TokenType, what: str | None = None) -> Token:
        t = self._peek()
        if t.type is not tt:
            raise ParseError(
                f"Expected {what or tt.name} but found {self._describe(t)}",
                line=t.line, col=t.col,
            )
        return self._advance()

    def _skip_newlines(self) -> None:
        while self._check(TT.NEWLINE):
            self._advance()

    @staticmethod
    def _describe(t: Token) -> str:
        if t.type is TT.EOF:
            return "the end of the scroll"
        if t.type is TT.NEWLINE:
            return "the end of the line"
        if t.type is TT.IDENT:
            return f"the name '{t.value}'"
        if t.type is TT.NUMBER:
            return f"the number {t.value!r}"
        if t.type is TT.STRING:
            return f"the text {t.value!r}"
        return f"'{t.value}'"

    # -- statement lists ---------------------------------------------------

    def _parse_body(self, *, end: set[TokenType], missing: str,
                    opening: Token | None, legacy_for: bool = False) -> list:
        """Parse statements until a token in ``end`` (left unconsumed).

        With ``legacy_for``, END CREATION / END RITE / EOF also end the body
        without being consumed (the original sample.godcode's open FOR).
        Otherwise hitting them raises ParseError naming what was missing.
        """
        stmts: list = []
        while True:
            self._skip_newlines()
            t = self._peek()
            if t.type in end:
                return stmts
            if t.type is TT.EOF:
                if legacy_for:
                    return stmts
                raise ParseError(
                    f"The scroll ends before {missing}; "
                    + (f"the {opening.value} opened on line {opening.line} "
                       "was never closed" if opening else
                       "every opened block must be closed"),
                    line=t.line, col=t.col,
                )
            if t.type is TT.END and self._peek_next().type in (TT.CREATION, TT.RITE):
                if legacy_for:
                    return stmts
                raise ParseError(
                    f"Found {t.value} {self._peek_next().value} before {missing}; "
                    "every opened block must be closed in its own time",
                    line=t.line, col=t.col,
                )
            stmts.append(self._parse_statement())

    # -- top level ---------------------------------------------------------

    def _parse_creation_block(self) -> A.CreationBlock:
        b = self._expect(TT.BEGIN)
        self._expect(TT.CREATION)
        self._skip_newlines()
        stmts = self._parse_body(end={TT.END}, missing="END CREATION", opening=b)
        self._expect(TT.END)
        self._expect(TT.CREATION)
        return A.CreationBlock(statements=stmts, line=b.line, col=b.col)

    # -- statements --------------------------------------------------------

    def _parse_statement(self):
        t = self._peek()
        tt = t.type
        if tt is TT.DECLARE:
            return self._parse_declare()
        if tt is TT.BREATHE:
            return self._parse_breathe()
        if tt is TT.REVEAL:
            return self._parse_reveal()
        if tt is TT.PROPHESY:
            return self._parse_prophesy()
        if tt is TT.ASCEND:
            self._advance()
            return A.Ascend(line=t.line, col=t.col)
        if tt is TT.REFLECT:
            self._advance()
            return A.Reflect(line=t.line, col=t.col)
        if tt is TT.BLESS:
            return self._parse_named_single(TT.BLESS, A.Bless)
        if tt is TT.ANOINT:
            return self._parse_named_single(TT.ANOINT, A.Anoint)
        if tt is TT.SEAL:
            self._advance()
            return A.SealStmt(expr=self._parse_expr(), line=t.line, col=t.col)
        if tt is TT.TESTIFY:
            self._advance()
            return A.Testify(expr=self._parse_expr(), line=t.line, col=t.col)
        if tt is TT.IF:
            return self._parse_if()
        if tt is TT.FOR:
            return self._parse_for()
        if tt is TT.WHILE:
            return self._parse_while()
        if tt is TT.BREAK:
            return self._parse_break()
        if tt is TT.CONTINUE:
            return self._parse_continue()
        if tt is TT.TRY:
            return self._parse_try()
        if tt is TT.DEFINE:
            return self._parse_define_rite()
        if tt is TT.RETURN:
            return self._parse_return()
        if tt is TT.IMPORT:
            return self._parse_import()
        if tt in _EXPR_STARTS:
            expr = self._parse_expr()
            return A.ExprStmt(expr=expr, line=t.line, col=t.col)
        raise ParseError(
            f"Unexpected {self._describe(t)}; a decree must begin with "
            "a holy word (DECLARE, IF, FOR, REVEAL, ...)",
            line=t.line, col=t.col,
        )

    def _parse_named_single(self, tt: TokenType, node_cls):
        kw = self._expect(tt)
        name = self._expect(TT.IDENT, "a name").value
        return node_cls(name=name, line=kw.line, col=kw.col)

    def _parse_declare(self) -> A.Declare:
        d = self._expect(TT.DECLARE)
        # --- v4.0: DECLARE INTENT "words..." ON rite_name ---
        # INTENT and ON are soft keywords (plain identifiers by text), so
        # `DECLARE intent AS x` keeps working: only DECLARE followed by the
        # word INTENT and then a quoted string takes the intent path.
        nxt, nxt2 = self._peek(), self._peek_next()
        if (nxt.type is TT.IDENT and nxt.value.upper() == "INTENT"
                and nxt2.type is TT.STRING):
            self._advance()  # the word INTENT
            text = self._expect(TT.STRING, "the intent in quotes").value
            on = self._peek()
            if not (on.type is TT.IDENT and on.value.upper() == "ON"):
                raise ParseError(
                    'DECLARE INTENT needs ON and a rite name, as in '
                    'DECLARE INTENT "bring peace" ON evening_blessing',
                    line=on.line, col=on.col,
                )
            self._advance()  # the word ON
            rite = self._expect(TT.IDENT, "a rite name").value
            return A.DeclareIntent(text=text, rite=rite, line=d.line, col=d.col)
        # --- permission manifests: DECLARE PERMISSION TO <power> ---
        # PERMISSION and TO are soft keywords (plain identifiers by text), so
        # `DECLARE permission AS x` keeps working: only DECLARE followed by
        # the word PERMISSION takes the manifest path.
        if (nxt.type is TT.IDENT and nxt.value.upper() == "PERMISSION"
                and nxt2.type is TT.IDENT and nxt2.value.upper() == "TO"):
            return self._parse_declare_permission(d)
        # --- end permission manifests ---
        name = self._expect(TT.IDENT, "a name to declare").value
        self._expect(TT.AS)
        items = [self._parse_expr()]
        while self._check(TT.COMMA):
            self._advance()
            items.append(self._parse_expr())
        if len(items) == 1:
            value = items[0]
        else:
            value = A.ListLiteral(items=items, line=items[0].line, col=items[0].col)
        return A.Declare(name=name, value=value, line=d.line, col=d.col)

    def _parse_declare_permission(self, d) -> A.DeclarePermission:
        """Parse DECLARE PERMISSION TO <power> -- the permission manifest."""
        self._advance()  # the word PERMISSION
        self._advance()  # the word TO
        line, col = d.line, d.col

        def word_is(text: str) -> bool:
            t = self._peek()
            return t.type is TT.IDENT and t.value.upper() == text

        def eat_word(text: str) -> None:
            t = self._peek()
            if not (t.type is TT.IDENT and t.value.upper() == text):
                raise ParseError(
                    f"DECLARE PERMISSION TO expects the word {text} here, "
                    f"as in DECLARE PERMISSION TO {text} ...",
                    line=t.line, col=t.col,
                )
            self._advance()

        def eat_string(what: str) -> str:
            return self._expect(TT.STRING, what).value

        if word_is("READ"):
            self._advance()
            return A.DeclarePermission(
                power="read",
                target=eat_string('a path in quotes, as in DECLARE PERMISSION TO READ "data/"'),
                line=line, col=col,
            )
        if word_is("WRITE"):
            self._advance()
            return A.DeclarePermission(
                power="write",
                target=eat_string('a path in quotes, as in DECLARE PERMISSION TO WRITE "out/"'),
                line=line, col=col,
            )
        if word_is("SPEAK"):
            self._advance()
            eat_word("WITH")
            return A.DeclarePermission(
                power="network",
                target=eat_string('a host in quotes, as in DECLARE PERMISSION TO SPEAK WITH "api.example.com"'),
                line=line, col=col,
            )
        if word_is("ASK"):
            self._advance()
            eat_word("THE")
            eat_word("WORLD")
            return A.DeclarePermission(power="stdin", target=None, line=line, col=col)
        if word_is("SUMMON"):
            self._advance()
            return A.DeclarePermission(
                power="summon",
                target=eat_string('a verb name in quotes, as in DECLARE PERMISSION TO SUMMON "reports.weekly"'),
                line=line, col=col,
            )
        t = self._peek()
        raise ParseError(
            "DECLARE PERMISSION TO grants one power: READ a path, WRITE a "
            "path, SPEAK WITH a host, ASK THE WORLD, or SUMMON a verb. "
            f"I heard '{t.value}'.",
            line=t.line, col=t.col,
        )

    def _parse_breathe(self) -> A.Breathe:
        b = self._expect(TT.BREATHE)
        self._expect(TT.LIFE)
        self._expect(TT.INTO)
        name = self._expect(TT.IDENT, "a name to breathe into").value
        return A.Breathe(name=name, line=b.line, col=b.col)

    def _parse_reveal(self) -> A.Reveal:
        r = self._expect(TT.REVEAL)
        self._expect(TT.LPAREN)
        expr = self._parse_expr()
        self._expect(TT.RPAREN)
        return A.Reveal(expr=expr, line=r.line, col=r.col)

    def _parse_prophesy(self) -> A.Prophesy:
        p = self._expect(TT.PROPHESY)
        line_no = p.line
        parts: list[str] = []
        while True:
            t = self._peek()
            if t.type in (TT.NEWLINE, TT.EOF) or t.line != line_no:
                break
            parts.append(str(t.value))
            self._advance()
        return A.Prophesy(text=" ".join(parts), line=p.line, col=p.col)

    def _parse_if(self) -> A.IfStmt:
        i = self._expect(TT.IF)
        cond = self._parse_expr()
        self._expect(TT.THEN)
        if self._check(TT.NEWLINE):
            self._skip_newlines()
            then_body = self._parse_body(end={TT.ENDIF, TT.ELSE},
                                        missing="ENDIF", opening=i)
            else_body: list = []
            has_else = False
            if self._check(TT.ELSE):
                self._advance()
                has_else = True
                self._skip_newlines()
                else_body = self._parse_body(end={TT.ENDIF},
                                            missing="ENDIF", opening=i)
            self._expect(TT.ENDIF)
        else:
            then_body = [self._parse_statement()]
            else_body = []
            has_else = False
            if self._check(TT.ELSE):
                self._advance()
                has_else = True
                else_body = [self._parse_statement()]
        return A.IfStmt(cond=cond, then_body=then_body, else_body=else_body,
                        has_else=has_else, line=i.line, col=i.col)

    def _parse_for(self) -> A.ForLoop:
        f = self._expect(TT.FOR)
        var = self._expect(TT.IDENT, "a name for the traveler").value
        self._expect(TT.IN)
        iterable = self._parse_expr()
        self._loop_depth += 1
        try:
            if self._check(TT.NEWLINE):
                body = self._parse_body(end={TT.ENDFOR}, missing="ENDFOR",
                                        opening=f, legacy_for=True)
                if self._check(TT.ENDFOR):
                    self._advance()
            else:
                body = [self._parse_statement()]
        finally:
            self._loop_depth -= 1
        return A.ForLoop(var=var, iterable=iterable, body=body,
                         line=f.line, col=f.col)

    def _parse_while(self) -> A.WhileLoop:
        w = self._expect(TT.WHILE)
        cond = self._parse_expr()
        self._expect(TT.DO)
        self._loop_depth += 1
        try:
            if self._check(TT.NEWLINE):
                body = self._parse_body(end={TT.ENDWHILE}, missing="ENDWHILE",
                                        opening=w)
                self._expect(TT.ENDWHILE)
            else:
                body = [self._parse_statement()]
        finally:
            self._loop_depth -= 1
        return A.WhileLoop(cond=cond, body=body, line=w.line, col=w.col)

    def _parse_break(self) -> A.Break:
        b = self._advance()
        if self._loop_depth == 0:
            raise ParseError(
                "BREAK can only be used inside a loop. It was spoken with "
                "no cycle to release. Place it within a FOR or a WHILE.",
                line=b.line, col=b.col,
            )
        return A.Break(line=b.line, col=b.col)

    def _parse_continue(self) -> A.Continue:
        c = self._advance()
        if self._loop_depth == 0:
            raise ParseError(
                "CONTINUE can only be used inside a loop. It was spoken with "
                "no cycle to turn. Place it within a FOR or a WHILE.",
                line=c.line, col=c.col,
            )
        return A.Continue(line=c.line, col=c.col)

    def _parse_try(self) -> A.TryStmt:
        t = self._expect(TT.TRY)
        if not self._check(TT.NEWLINE):
            raise ParseError(
                "TRY opens a block: place its works on the following lines, "
                "then CATCH ... ENDTRY",
                line=t.line, col=t.col,
            )
        self._skip_newlines()
        try_body = self._parse_body(end={TT.CATCH}, missing="CATCH", opening=t)
        self._expect(TT.CATCH)
        if self._check(TT.IDENT):
            error_name = self._advance().value
        else:
            error_name = "ERROR"
        self._skip_newlines()
        catch_body = self._parse_body(end={TT.ENDTRY}, missing="ENDTRY",
                                      opening=t)
        self._expect(TT.ENDTRY)
        return A.TryStmt(try_body=try_body, catch_body=catch_body,
                         error_name=error_name, line=t.line, col=t.col)

    def _parse_define_rite(self) -> A.DefineRite:
        d = self._expect(TT.DEFINE)
        self._expect(TT.RITE)
        name = self._expect(TT.IDENT, "a name for the rite").value
        self._expect(TT.LPAREN)
        params: list[str] = []
        if not self._check(TT.RPAREN):
            params.append(self._expect(TT.IDENT, "a parameter name").value)
            while self._check(TT.COMMA):
                self._advance()
                params.append(self._expect(TT.IDENT, "a parameter name").value)
        self._expect(TT.RPAREN)
        # A rite body is a fresh boundary: BREAK/CONTINUE inside it may only
        # answer to loops within the rite, never to a caller's loop.
        saved_depth, self._loop_depth = self._loop_depth, 0
        try:
            if self._check(TT.NEWLINE):
                self._skip_newlines()
                body = self._parse_body(end={TT.END}, missing="END RITE", opening=d)
            else:
                # inline single-statement body, e.g. DEFINE RITE f(x) SEAL x END RITE
                body = [self._parse_statement()]
                self._skip_newlines()
        finally:
            self._loop_depth = saved_depth
        self._expect(TT.END)
        self._expect(TT.RITE)
        return A.DefineRite(name=name, params=params, body=body,
                            line=d.line, col=d.col)

    def _parse_return(self) -> A.Return:
        r = self._expect(TT.RETURN)
        if self._peek().type in _RETURN_TERMINATORS:
            return A.Return(expr=None, line=r.line, col=r.col)
        return A.Return(expr=self._parse_expr(), line=r.line, col=r.col)

    def _parse_import(self) -> A.Import:
        im = self._expect(TT.IMPORT)
        path = self._expect(TT.STRING, "a scroll path in quotes").value
        return A.Import(path=path, line=im.line, col=im.col)

    # -- expressions -------------------------------------------------------

    def _parse_expr(self):
        return self._parse_or()

    def _parse_or(self):
        left = self._parse_and()
        while self._check(TT.OR):
            op = self._advance()
            right = self._parse_and()
            left = A.BinaryOp(op="or", left=left, right=right,
                              line=op.line, col=op.col)
        return left

    def _parse_and(self):
        left = self._parse_not_low()
        while self._check(TT.AND):
            op = self._advance()
            right = self._parse_not_low()
            left = A.BinaryOp(op="and", left=left, right=right,
                              line=op.line, col=op.col)
        return left

    def _parse_not_low(self):
        if self._check(TT.NOT):
            op = self._advance()
            return A.UnaryOp(op="not", operand=self._parse_not_low(),
                             line=op.line, col=op.col)
        return self._parse_comparison()

    _COMPARISON_OPS = {
        TT.EQ: "==", TT.NEQ: "!=", TT.LT: "<",
        TT.GT: ">", TT.LTE: "<=", TT.GTE: ">=",
    }

    def _parse_comparison(self):
        left = self._parse_additive()
        while True:
            t = self._peek()
            if t.type is TT.IS:
                self._advance()
                if self._check(TT.NOT):
                    self._advance()
                    op = "!="
                else:
                    op = "=="
            elif t.type in self._COMPARISON_OPS:
                self._advance()
                op = self._COMPARISON_OPS[t.type]
            else:
                break
            right = self._parse_additive()
            left = A.BinaryOp(op=op, left=left, right=right,
                              line=t.line, col=t.col)
        return left

    def _parse_additive(self):
        left = self._parse_multiplicative()
        while self._peek().type in (TT.PLUS, TT.MINUS):
            op = self._advance()
            right = self._parse_multiplicative()
            left = A.BinaryOp(op=op.value, left=left, right=right,
                              line=op.line, col=op.col)
        return left

    def _parse_multiplicative(self):
        left = self._parse_unary()
        while self._peek().type in (TT.STAR, TT.SLASH, TT.PERCENT):
            op = self._advance()
            right = self._parse_unary()
            left = A.BinaryOp(op=op.value, left=left, right=right,
                              line=op.line, col=op.col)
        return left

    def _parse_unary(self):
        t = self._peek()
        if t.type is TT.MINUS:
            self._advance()
            return A.UnaryOp(op="-", operand=self._parse_unary(),
                             line=t.line, col=t.col)
        if t.type is TT.NOT:
            self._advance()
            return A.UnaryOp(op="not", operand=self._parse_unary(),
                             line=t.line, col=t.col)
        return self._parse_postfix()

    def _parse_postfix(self):
        obj = self._parse_primary()
        while self._check(TT.LBRACKET):
            lb = self._advance()
            index = self._parse_expr()
            self._expect(TT.RBRACKET)
            obj = A.Index(obj=obj, index=index, line=lb.line, col=lb.col)
        return obj

    def _parse_primary(self):
        t = self._peek()
        tt = t.type
        if tt is TT.NUMBER:
            self._advance()
            return A.Literal(value=t.value, line=t.line, col=t.col)
        if tt is TT.STRING:
            self._advance()
            if "{" in t.value or "}}" in t.value:
                return self._parse_interpolated(t)
            return A.Literal(value=t.value, line=t.line, col=t.col)
        if tt is TT.TRUE:
            self._advance()
            return A.Literal(value=True, line=t.line, col=t.col)
        if tt is TT.FALSE:
            self._advance()
            return A.Literal(value=False, line=t.line, col=t.col)
        if tt is TT.VOID:
            self._advance()
            return A.Literal(value=None, line=t.line, col=t.col)
        if tt is TT.IDENT:
            self._advance()
            if self._check(TT.LPAREN):
                self._advance()
                args = self._parse_args()
                self._expect(TT.RPAREN)
                return A.CallExpr(callee=t.value, args=args,
                                  line=t.line, col=t.col)
            return A.Identifier(name=t.value, line=t.line, col=t.col)
        if tt is TT.INVOKE:
            self._advance()
            name = self._expect(TT.IDENT, "a rite name").value
            self._expect(TT.LPAREN)
            args = self._parse_args()
            self._expect(TT.RPAREN)
            return A.CallExpr(callee=name, args=args, line=t.line, col=t.col)
        if tt is TT.LPAREN:
            self._advance()
            expr = self._parse_expr()
            self._expect(TT.RPAREN)
            return expr
        if tt is TT.LBRACKET:
            self._advance()
            items = []
            if not self._check(TT.RBRACKET):
                items.append(self._parse_expr())
                while self._check(TT.COMMA):
                    self._advance()
                    items.append(self._parse_expr())
            self._expect(TT.RBRACKET)
            return A.ListLiteral(items=items, line=t.line, col=t.col)
        raise ParseError(
            f"Expected a value or name but found {self._describe(t)}",
            line=t.line, col=t.col,
        )

    # -- string interpolation: "grace upon {name}" ----------------------------

    def _parse_interpolated(self, tok):
        """Build an InterpolatedString from a STRING token's value.

        ``{expr}`` breathes the expression's revealed value into the string;
        ``{{`` and ``}}`` write a plain brace; a lone ``}`` stays a plain brace.
        """
        src = tok.value
        parts: list = []
        buf: list[str] = []
        i, n = 0, len(src)
        while i < n:
            ch = src[i]
            if ch == "{" and src[i + 1 : i + 2] == "{":
                buf.append("{")
                i += 2
                continue
            if ch == "}" and src[i + 1 : i + 2] == "}":
                buf.append("}")
                i += 2
                continue
            if ch == "{":
                end = self._find_interpolation_end(src, i, tok)
                inner = src[i + 1 : end]
                if not inner.strip():
                    raise ParseError(
                        "empty braces breathe nothing into the string; "
                        "place a name or an expression between '{' and '}', "
                        "or write '{{}}' for plain braces",
                        line=tok.line, col=tok.col + i,
                    )
                if buf:
                    parts.append("".join(buf))
                    buf = []
                parts.append(self._parse_braced_expr(inner, tok, i))
                i = end + 1
                continue
            buf.append(ch)
            i += 1
        if buf:
            parts.append("".join(buf))
        return A.InterpolatedString(parts=parts, source=src,
                                    line=tok.line, col=tok.col)

    @staticmethod
    def _find_interpolation_end(src: str, start: int, tok) -> int:
        """Index of the ``}`` closing the ``{`` at ``start``.

        Nested braces count toward the depth, and braces inside a quoted
        string are skipped, so ``"{greet("hi {name}")}"`` seals correctly.
        """
        depth = 0
        in_string = False
        i, n = start, len(src)
        while i < n:
            c = src[i]
            if in_string:
                if c == "\\":
                    i += 2
                    continue
                if c == '"':
                    in_string = False
            elif c == '"':
                in_string = True
            elif c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        raise ParseError(
            "an opening '{' breathes a blessing that was never sealed; "
            "close it with '}' or write '{{' for a plain brace",
            line=tok.line, col=tok.col + start,
        )

    def _parse_braced_expr(self, inner: str, tok, offset: int):
        """Parse the text between one pair of braces as a single expression."""
        tokens = [t for t in Lexer(inner, tongue=self._tongue).lex()
                  if t.type not in (TT.NEWLINE, TT.EOF)]
        tokens.append(Token(TT.EOF, "", tok.line, tok.col + offset))
        sub = Parser(tokens)
        expr = sub._parse_expr()
        if not sub._check(TT.EOF):
            raise ParseError(
                "the blessing between '{' and '}' could not be understood; "
                "only one expression may dwell there",
                line=tok.line, col=tok.col + offset,
            )
        return expr

    def _parse_args(self) -> list:
        args = []
        if not self._check(TT.RPAREN):
            args.append(self._parse_expr())
            while self._check(TT.COMMA):
                self._advance()
                args.append(self._parse_expr())
        return args

files.godcode/permissions.py:
"""Permission manifests for God Code.

A scroll may declare what it is allowed to touch:

    DECLARE PERMISSION TO READ "data/"
    DECLARE PERMISSION TO WRITE "out/"
    DECLARE PERMISSION TO SPEAK WITH "api.example.com"
    DECLARE PERMISSION TO ASK THE WORLD
    DECLARE PERMISSION TO SUMMON "reports.weekly"

The manifest is collected from the scroll's top-level decrees before the
run begins. It never widens what the host allows: the effective grant is
always *host policy intersect manifest*. A scroll that reaches for a
power it did not declare is counselled and stopped with a
``SandboxViolation``.

Imported scrolls contribute their own manifests; grants compose by union
(a run may use any power granted by any scroll it breathes in). Relative
path patterns are resolved against the directory of the scroll that
declares them.
"""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

__all__ = [
    "PermissionManifest",
    "collect_manifest",
    "POWERS",
]

# The five declared powers, in the order they read in counsel.
POWERS = ("read", "write", "network", "stdin", "summon")

# AST node class name we collect from, so this module never imports the
# parser or interpreter (no import cycles).
_DECLARE_PERMISSION_NODE = "DeclarePermission"


def _node_is_permission(stmt: Any) -> bool:
    return type(stmt).__name__ == _DECLARE_PERMISSION_NODE


@dataclass
class PermissionManifest:
    """The declared powers of one scroll or one whole run.

    Path patterns are stored as absolute directory prefixes. A pattern
    naming a file grants that exact file; a pattern naming a directory
    grants everything beneath it.
    """

    read_paths: tuple[str, ...] = ()
    write_paths: tuple[str, ...] = ()
    hosts: tuple[str, ...] = ()
    stdin: bool = False
    summons: tuple[str, ...] = ()

    def __bool__(self) -> bool:
        return bool(
            self.read_paths
            or self.write_paths
            or self.hosts
            or self.stdin
            or self.summons
        )

    # -- composition ----------------------------------------------------

    def merge(self, other: "PermissionManifest") -> "PermissionManifest":
        """Union two manifests: grants only ever grow by import."""
        def _union(a: tuple[str, ...], b: tuple[str, ...]) -> tuple[str, ...]:
            seen: list[str] = []
            for item in (*a, *b):
                if item not in seen:
                    seen.append(item)
            return tuple(seen)

        return PermissionManifest(
            read_paths=_union(self.read_paths, other.read_paths),
            write_paths=_union(self.write_paths, other.write_paths),
            hosts=_union(self.hosts, other.hosts),
            stdin=self.stdin or other.stdin,
            summons=_union(self.summons, other.summons),
        )

    # -- enforcement ----------------------------------------------------

    @staticmethod
    def _under(path: str, granted: tuple[str, ...]) -> bool:
        try:
            resolved = os.path.realpath(path)
        except OSError:
            return False
        for base in granted:
            if resolved == base or resolved.startswith(base + os.sep):
                return True
        return False

    def allows_read(self, path: str) -> bool:
        return self._under(path, self.read_paths)

    def allows_write(self, path: str) -> bool:
        return self._under(path, self.write_paths)

    def allows_host(self, url: str) -> bool:
        try:
            host = (urlparse(url).hostname or "").lower()
        except (ValueError, AttributeError):
            return False
        return any(host == granted or host.endswith("." + granted)
                   for granted in self.hosts)

    def allows_summon(self, verb: str) -> bool:
        return any(verb == name or verb.startswith(name + ".")
                   for name in self.summons)

    # -- machine interfaces ----------------------------------------------

    def to_json(self) -> dict:
        """Stable shape for agents: `godcode permissions --json`."""
        return {
            "read": list(self.read_paths),
            "write": list(self.write_paths),
            "network": list(self.hosts),
            "stdin": self.stdin,
            "summon": list(self.summons),
        }

    def describe(self) -> list[str]:
        """One human line per granted power, for counsel and CLI output."""
        lines: list[str] = []
        for path in self.read_paths:
            lines.append(f"may read from {path}")
        for path in self.write_paths:
            lines.append(f"may write to {path}")
        for host in self.hosts:
            lines.append(f"may speak with {host}")
        if self.stdin:
            lines.append("may ask the outer world")
        for name in self.summons:
            lines.append(f"may summon {name}")
        return lines


def collect_manifest(statements: list, base_dir: str | Path | None) -> PermissionManifest:
    """Gather DECLARE PERMISSION decrees from top-level statements.

    Looks at the scroll's top level and inside any top-level creation
    blocks. ``base_dir`` resolves relative path patterns to absolute
    prefixes; ``None`` resolves them against the current working
    directory.
    """
    base = Path(base_dir) if base_dir else Path.cwd()
    reads: list[str] = []
    writes: list[str] = []
    hosts: list[str] = []
    stdin = False
    summons: list[str] = []

    def _resolve(pattern: str) -> str:
        candidate = Path(pattern)
        if not candidate.is_absolute():
            candidate = base / candidate
        try:
            return os.path.realpath(candidate)
        except OSError:  # pragma: no cover - defensive
            return str(candidate)

    def _visit(stmts: list, inside_block: bool) -> None:
        nonlocal stdin
        for stmt in stmts:
            if _node_is_permission(stmt):
                power = getattr(stmt, "power", "")
                target = getattr(stmt, "target", None)
                if power == "read" and target:
                    reads.append(_resolve(target))
                elif power == "write" and target:
                    writes.append(_resolve(target))
                elif power == "network" and target:
                    hosts.append(target.strip().lower())
                elif power == "stdin":
                    stdin = True
                elif power == "summon" and target:
                    summons.append(target.strip())
            elif (not inside_block
                    and type(stmt).__name__ == "CreationBlock"):
                _visit(getattr(stmt, "statements", []), True)

    _visit(statements, False)

    def _dedupe(items: list[str]) -> tuple[str, ...]:
        seen: list[str] = []
        for item in items:
            if item not in seen:
                seen.append(item)
        return tuple(seen)

    return PermissionManifest(
        read_paths=_dedupe(reads),
        write_paths=_dedupe(writes),
        hosts=_dedupe(hosts),
        stdin=stdin,
        summons=_dedupe(summons),
    )

files.godcode/registry.py:
"""Pillar 2 — the Scroll Registry: installable, versioned God Code scrolls.

A scroll is a directory holding a ``scroll.toml`` manifest beside its entry
``.god`` file.  The local registry (``registry/`` at the repo root) is the
source of truth: ``publish`` copies a scroll into
``registry/scrolls/<name>/<version>/`` and records it in
``registry/index.json``; ``install`` copies from there into
``~/.godcode/scrolls/<name>/<version>/`` (user-global) or
``.godcode/scrolls/`` (project-local, wins over user-global).

requires-python is >=3.10, so ``tomllib`` (3.11+) is off the table: the
manifest parser below is a hand-rolled TOML subset covering exactly the
keys this registry defines.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Optional

try:  # the package version is the engine version; tolerate odd import orders
    from godcode import __version__ as ENGINE_VERSION
except Exception:  # pragma: no cover - defensive
    ENGINE_VERSION = "2.0.0"

# ---------------------------------------------------------------------------
# errors


class ScrollError(Exception):
    """Raised when a manifest, publish, install, or lookup fails."""


class ScrollNotFoundError(ScrollError):
    """Raised when a scroll cannot be found in a registry.

    Kept distinct from ScrollError so the CLI can fall back from the local
    registry to the remote one on exactly this failure.
    """


# ---------------------------------------------------------------------------
# manifest parsing (TOML subset: key = "value" pairs, # comments)


MANIFEST_KEYS = frozenset(
    {"name", "version", "author", "description", "entry", "godcode",
     "dependencies"}
)
REQUIRED_KEYS = frozenset(
    {"name", "version", "author", "description", "entry", "godcode"}
)  # dependencies is optional
_NAME_RE = re.compile(r"^[a-z][a-z0-9-]*[a-z0-9]$|^[a-z]$")
_SEMVER_RE = re.compile(r"^(\d+)\.(\d+)\.(\d+)$")
_REQ_CLAUSE_RE = re.compile(r"^(>=|<=|==|!=|>|<)\s*(\d+(?:\.\d+){0,2})$")

# Human-readable blurbs shown in errors; keep them short.
_KEY_HINTS = {
    "name": 'e.g. name = "json-tools"',
    "version": 'e.g. version = "1.0.0"',
    "author": 'e.g. author = "Ama Seretse"',
    "description": 'e.g. description = "JSON helpers written in God Code"',
    "entry": 'e.g. entry = "json-tools.god"',
    "godcode": 'e.g. godcode = ">=2.0"',
    "dependencies": 'e.g. dependencies = "json-tools >= 1.0.0, dates"',
}


def _strip_comment(line: str) -> str:
    """Cut a trailing ``#`` comment, ignoring ``#`` inside quoted strings."""
    in_quote: str | None = None
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quote:
            if ch == "\\" and in_quote == '"':
                i += 2
                continue
            if ch == in_quote:
                in_quote = None
        elif ch in ('"', "'"):
            in_quote = ch
        elif ch == "#":
            return line[:i]
        i += 1
    return line


def _parse_toml_value(raw: str, source: str, lineno: int) -> str:
    """Parse a quoted TOML string value (double- or single-quoted)."""
    if len(raw) >= 2 and raw[0] == '"' and raw[-1] == '"':
        out: list[str] = []
        i = 1
        while i < len(raw) - 1:
            ch = raw[i]
            if ch == "\\":
                i += 1
                if i >= len(raw) - 1:
                    raise ScrollError(
                        f"{source}:{lineno}: dangling backslash in manifest value"
                    )
                esc = raw[i]
                out.append({"n": "\n", "t": "\t", "r": "\r"}.get(esc, esc))
            else:
                out.append(ch)
            i += 1
        return "".join(out)
    if len(raw) >= 2 and raw[0] == "'" and raw[-1] == "'":
        return raw[1:-1]  # literal string: no escapes
    raise ScrollError(
        f"{source}:{lineno}: manifest values must be quoted strings "
        f"(got {raw!r})"
    )


def parse_manifest(text: str, source: str = "<scroll.toml>") -> dict[str, str]:
    """Parse and validate a ``scroll.toml`` manifest. Returns a plain dict."""
    data: dict[str, str] = {}
    for lineno, raw_line in enumerate(text.splitlines(), 1):
        line = _strip_comment(raw_line).strip()
        if not line:
            continue
        if "=" not in line:
            raise ScrollError(
                f"{source}:{lineno}: expected `key = \"value\"`, got {line!r}"
            )
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_-]*", key):
            raise ScrollError(f"{source}:{lineno}: bad manifest key {key!r}")
        if key in data:
            raise ScrollError(
                f"{source}:{lineno}: duplicate manifest key {key!r}"
            )
        data[key] = _parse_toml_value(value, source, lineno)

    unknown = sorted(set(data) - MANIFEST_KEYS)
    if unknown:
        raise ScrollError(
            f"{source}: unknown manifest key(s) {', '.join(unknown)}; "
            "known keys: " + ", ".join(sorted(MANIFEST_KEYS))
        )
    missing = sorted(REQUIRED_KEYS - set(data))
    if missing:
        hints = "; ".join(_KEY_HINTS[k] for k in missing)
        raise ScrollError(
            f"{source}: missing required manifest key(s) "
            f"{', '.join(missing)} ({hints})"
        )

    name = data["name"]
    if not _NAME_RE.match(name):
        raise ScrollError(
            f"{source}: name {name!r} must be lowercase letters, digits and "
            "hyphens, starting with a letter"
        )
    parse_semver(data["version"], source=source)  # validates
    entry = data["entry"]
    if not entry or "/" in entry or "\\" in entry or entry.startswith("."):
        raise ScrollError(
            f"{source}: entry must be a plain filename, got {entry!r}"
        )
    req = data["godcode"]
    if not requirement_satisfied(req):
        raise ScrollError(
            f"{source}: this scroll needs God Code {req}, "
            f"but the engine is {ENGINE_VERSION}"
        )
    if "dependencies" in data:
        parse_dependencies(data["dependencies"], source=source)
    return data


def read_manifest(path: str | os.PathLike) -> dict[str, str]:
    """Read, parse, and validate the manifest at ``path``."""
    path = Path(path)
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as exc:
        raise ScrollError(f"cannot read manifest {path}: {exc}") from exc
    return parse_manifest(text, source=str(path))


# ---------------------------------------------------------------------------
# semver-ish versions (X.Y.Z only)


def parse_semver(text: str, source: str = "<manifest>") -> tuple[int, int, int]:
    """Parse ``X.Y.Z``; raise ScrollError on anything else."""
    match = _SEMVER_RE.match(text.strip())
    if not match:
        raise ScrollError(
            f"{source}: version must look like X.Y.Z, got {text!r}"
        )
    return int(match.group(1)), int(match.group(2)), int(match.group(3))


def compare_versions(a: str, b: str) -> int:
    """-1 if a < b, 0 if equal, 1 if a > b (numeric per component)."""
    ta, tb = parse_semver(a), parse_semver(b)
    return (ta > tb) - (ta < tb)


def latest_version(versions: list[str]) -> str:
    """The highest version; ties are impossible (versions are unique)."""
    if not versions:
        raise ScrollError("no versions to choose from")
    best = versions[0]
    for v in versions[1:]:
        if compare_versions(v, best) > 0:
            best = v
    return best


# ---------------------------------------------------------------------------
# godcode version requirements, e.g. ">=2.0, <4"


def _parse_requirement(req: str) -> list[tuple[str, tuple[int, ...]]]:
    clauses: list[tuple[str, tuple[int, ...]]] = []
    for part in req.split(","):
        part = part.strip()
        if not part:
            raise ScrollError(f"bad godcode requirement {req!r}: empty clause")
        match = _REQ_CLAUSE_RE.match(part)
        if not match:
            raise ScrollError(
                f"bad godcode requirement {req!r}: expected e.g. "
                f"'>=2.0', got {part!r}"
            )
        op, ver = match.group(1), match.group(2)
        clauses.append((op, tuple(int(x) for x in ver.split("."))))
    return clauses


def _pad(parts: tuple[int, ...], length: int) -> tuple[int, ...]:
    return parts + (0,) * (length - len(parts))


def _clauses_satisfied(
    req: str, engine: str, clauses: list[tuple[str, tuple[int, ...]]]
) -> bool:
    engine_parts = _pad(tuple(int(x) for x in engine.split(".")), 3)
    for op, want in clauses:
        want = _pad(want, 3)
        if op == ">=" and not (engine_parts >= want):
            return False
        if op == "<=" and not (engine_parts <= want):
            return False
        if op == "==" and not (engine_parts == want):
            return False
        if op == "!=" and not (engine_parts != want):
            return False
        if op == ">" and not (engine_parts > want):
            return False
        if op == "<" and not (engine_parts < want):
            return False
    return True


def requirement_satisfied(req: str, engine: str = ENGINE_VERSION) -> bool:
    """True when ``engine`` satisfies a requirement like ``>=2.0``."""
    return _clauses_satisfied(req, engine, _parse_requirement(req))


# ---------------------------------------------------------------------------
# scroll dependencies, e.g. dependencies = "json-tools >= 1.0.0, dates"


def parse_dependencies(
    spec: str, source: str = "<scroll.toml>"
) -> list[tuple[str, str | None]]:
    """Parse a manifest ``dependencies`` value.

    Returns ``[(name, requirement)]``; requirement is None when the clause
    names the scroll with no version constraint.  A clause carries at most
    one requirement clause (``>= 1.0.0``); commas separate dependencies.
    """
    if not spec.strip():
        return []
    deps: list[tuple[str, str | None]] = []
    for part in spec.split(","):
        part = part.strip()
        if not part:
            raise ScrollError(
                f"{source}: bad dependencies {spec!r}: empty clause"
            )
        tokens = part.split()
        name = tokens[0]
        if not _NAME_RE.match(name):
            raise ScrollError(
                f"{source}: bad dependency name {name!r} in "
                f"dependencies {spec!r}"
            )
        requirement = " ".join(tokens[1:]) or None
        if requirement is not None:
            _parse_requirement(requirement)  # validates the clause shape
        if name in {n for n, _ in deps}:
            raise ScrollError(
                f"{source}: duplicate dependency {name!r} in "
                f"dependencies {spec!r}"
            )
        deps.append((name, requirement))
    return deps


def render_manifest(manifest: dict[str, str]) -> str:
    """Render a manifest dict as ``scroll.toml`` text."""
    lines: list[str] = []
    for key in ("name", "version", "author", "description", "entry",
                "godcode", "dependencies"):
        if key in manifest:
            value = manifest[key].replace("\\", "\\\\").replace('"', '\\"')
            lines.append(f'{key} = "{value}"')
    return "\n".join(lines) + "\n"


# ---------------------------------------------------------------------------
# the registry


def _default_registry_root() -> Path:
    return Path(__file__).resolve().parent.parent / "registry"


def _sha256_file(path: Path) -> str:
    """Hex sha256 of a file's bytes."""
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _checksum_tree(root: Path) -> dict[str, str]:
    """sha256 for every file under ``root``, keyed by relative path."""
    checksums: dict[str, str] = {}
    for path in sorted(root.rglob("*")):
        if path.is_file():
            checksums[path.relative_to(root).as_posix()] = _sha256_file(path)
    return checksums


class ScrollRegistry:
    """Local scroll registry: publish into ``registry/``, install from it."""

    def __init__(
        self,
        registry_root: str | os.PathLike | None = None,
        home: str | os.PathLike | None = None,
        project_dir: str | os.PathLike | None = None,
    ) -> None:
        self.registry_root = Path(registry_root or _default_registry_root())
        self.scrolls_root = self.registry_root / "scrolls"
        self.index_path = self.registry_root / "index.json"
        self.home = Path(home or Path.home())  # honors $HOME, monkeypatchable
        self.user_dir = self.home / ".godcode" / "scrolls"
        self.project_dir = Path(project_dir or Path.cwd())
        self.project_scrolls_dir = self.project_dir / ".godcode" / "scrolls"

    # ------------------------------------------------------------- index ---

    def load_index(self) -> dict[str, Any]:
        """The published index; {} when nothing has been published yet."""
        if not self.index_path.is_file():
            return {}
        try:
            return json.loads(self.index_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise ScrollError(
                f"cannot read registry index {self.index_path}: {exc}"
            ) from exc

    def _save_index(self, index: dict[str, Any]) -> None:
        self.index_path.parent.mkdir(parents=True, exist_ok=True)
        self.index_path.write_text(
            json.dumps(index, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )

    # ----------------------------------------------------------- publish ---

    def publish(self, scroll_dir: str | os.PathLike) -> dict[str, str]:
        """Validate a scroll directory and publish it into the registry.

        Copies ``scroll_dir`` to ``registry/scrolls/<name>/<version>/`` and
        updates ``index.json``. Refuses when that exact version is already
        published. Returns the validated manifest.
        """
        src = Path(scroll_dir)
        if not src.is_dir():
            raise ScrollError(f"publish: {src} is not a directory")
        manifest_path = src / "scroll.toml"
        if not manifest_path.is_file():
            raise ScrollError(f"publish: {src} holds no scroll.toml manifest")
        manifest = read_manifest(manifest_path)

        name, version = manifest["name"], manifest["version"]
        if src.name != name:
            raise ScrollError(
                f"publish: manifest name {name!r} does not match directory "
                f"name {src.name!r}"
            )
        entry_path = src / manifest["entry"]
        if not entry_path.is_file():
            raise ScrollError(
                f"publish: entry file {manifest['entry']!r} not found in {src}"
            )

        index = self.load_index()
        published = index.get(name, {}).get("versions", [])
        if version in published:
            raise ScrollError(
                f"publish: {name} {version} is already in the registry. "
                "Bump the version to publish again"
            )

        dest = self.scrolls_root / name / version
        if dest.exists():
            raise ScrollError(
                f"publish: {dest} already exists on disk but is not indexed; "
                "remove it or repair the index first"
            )
        shutil.copytree(src, dest)

        versions = sorted(set(published) | {version},
                          key=lambda v: parse_semver(v))
        index[name] = {
            "name": name,
            "versions": versions,
            "latest": latest_version(versions),
            "manifest": manifest,
            "checksums": {
                **index.get(name, {}).get("checksums", {}),
                version: _checksum_tree(dest),
            },
        }
        self._save_index(index)
        return manifest

    # ----------------------------------------------------------- install ---

    def _remote_client(self, remote: bool | Any) -> Any | None:
        """A RemoteRegistry when ``remote`` asks for one, else None.

        ``remote`` may be True (build a default client), a RemoteRegistry
        instance (use it), or False/None (local only).
        """
        if remote is True:
            from godcode.remote_registry import RemoteRegistry

            return RemoteRegistry()
        return remote or None

    def resolve_version(self, name: str, version: str | None = None) -> str:
        """The version to install: ``version`` if given, else the latest."""
        index = self.load_index()
        entry = index.get(name)
        if entry is None:
            raise ScrollNotFoundError(
                f"install: {name!r} is not in the registry "
                f"({self.registry_root})"
            )
        versions: list[str] = entry["versions"]
        if version is None:
            return entry["latest"]
        if version not in versions:
            raise ScrollError(
                f"install: {name} has no version {version!r}; "
                f"published: {', '.join(versions)}"
            )
        return version

    def _choose_source(
        self,
        name: str,
        requirement: str | None,
        remote_client: Any | None,
        stack: tuple[str, ...],
    ) -> tuple[str, str, dict[str, Any] | None]:
        """Pick (version, source, info) for ``name`` under ``requirement``.

        ``requirement`` is None (any version), ``==X.Y.Z`` (exact, from
        ``--version`` or a pinned dependency), or a dep clause like
        ``>= 1.0.0``.  The local index always wins; the remote registry is
        consulted only when a client was passed and the local index cannot
        serve the requirement.
        """
        context = f" (needed by {' -> '.join(stack)})" if stack else ""
        index = self.load_index()
        entry = index.get(name)

        if requirement is not None and requirement.startswith("=="):
            exact = requirement[2:].strip()
            if entry is not None:
                if exact in entry["versions"]:
                    return exact, "local", None
                if remote_client is None:
                    raise ScrollError(
                        f"install: {name} has no version {exact!r}; "
                        f"published: {', '.join(entry['versions'])}"
                    )
                # else: fall through to the remote lookup below
        elif entry is not None:
            matching = [
                v
                for v in entry["versions"]
                if requirement is None
                or requirement_satisfied(requirement, v)
            ]
            if matching:
                return latest_version(matching), "local", None

        if remote_client is not None:
            try:
                info, matching = remote_client.versions_satisfying(
                    name, requirement
                )
            except ScrollError as exc:
                raise ScrollNotFoundError(
                    f"install: {name!r} is not in the local registry and the "
                    f"remote registry cannot serve it: {exc}{context}"
                ) from exc
            if matching:
                return matching[0], "remote", info
            raise ScrollNotFoundError(
                f"install: {name!r} is not in the local registry and the "
                f"remote registry has no version matching "
                f"{requirement or 'any'!r}{context}"
            )
        if entry is None:
            raise ScrollNotFoundError(
                f"install: {name!r} is not in the registry "
                f"({self.registry_root}){context}"
            )
        raise ScrollNotFoundError(
            f"install: {name!r} has no published version matching "
            f"{requirement!r}{context}"
        )

    def _manifest_for(
        self,
        name: str,
        version: str,
        source: str,
        info: dict[str, Any] | None,
    ) -> dict[str, str]:
        """The validated manifest for a chosen (name, version)."""
        if source == "local":
            return read_manifest(self.scrolls_root / name / version / "scroll.toml")
        from godcode.remote_registry import synthesized_manifest

        manifest = synthesized_manifest(name, info or {}, version)
        return parse_manifest(
            render_manifest(manifest), source=f"<remote {name} {version}>"
        )

    def _plan_install(
        self,
        name: str,
        requirement: str | None,
        stack: tuple[str, ...],
        remote_client: Any | None,
        plan: dict[str, dict[str, Any]],
    ) -> None:
        """Fill ``plan`` (insertion-ordered, dependencies first) with the
        scrolls this install needs, resolving versions and detecting cycles.
        """
        if name in stack:
            cycle = " -> ".join([*stack, name])
            raise ScrollError(
                f"dependency cycle detected: {cycle}. A scroll cannot depend "
                "on itself through a circle of dependencies; break the "
                "circle and publish again."
            )
        if name in plan:
            chosen = plan[name]["version"]
            if requirement is None or requirement_satisfied(requirement, chosen):
                return
            raise ScrollError(
                f"install: version conflict for {name!r}: this install "
                f"already resolved {chosen}, which does not satisfy "
                f"{requirement!r}"
            )
        version, source, info = self._choose_source(
            name, requirement, remote_client, stack
        )
        manifest = self._manifest_for(name, version, source, info)
        for dep_name, dep_req in parse_dependencies(
            manifest.get("dependencies", ""), source=f"<{name} {version}>"
        ):
            self._plan_install(dep_name, dep_req, stack + (name,),
                               remote_client, plan)
        plan[name] = {
            "name": name,
            "version": version,
            "source": source,
            "info": info,
            "manifest": manifest,
        }

    def _dependency_tree(
        self, manifest: dict[str, str], plan: dict[str, dict[str, Any]]
    ) -> dict[str, str]:
        """Resolved {dependency name: version} for a receipt."""
        tree: dict[str, str] = {}
        for dep_name, _ in parse_dependencies(manifest.get("dependencies", "")):
            if dep_name in plan:
                tree[dep_name] = plan[dep_name]["version"]
        return tree

    def _verify_checksums(self, name: str, version: str, src: Path) -> dict[str, str]:
        """Check published files against the checksums recorded on publish.

        Returns the recorded checksums (for the receipt).  Index entries
        written before checksums existed carry none and are trusted as-is.
        """
        index = self.load_index()
        recorded: dict[str, str] = (
            index.get(name, {}).get("checksums", {}) or {}
        ).get(version, {})
        for rel, expected in recorded.items():
            path = src / rel
            if not path.is_file():
                raise ScrollError(
                    f"install: {name} {version} is missing published file "
                    f"{rel!r} in the registry; republish the scroll"
                )
            actual = _sha256_file(path)
            if actual != expected:
                raise ScrollError(
                    f"install: checksum mismatch for {name} {version} file "
                    f"{rel!r}: the registry copy changed after publish "
                    f"(expected {expected[:12]}..., got {actual[:12]}...). "
                    "Republish the scroll to heal the registry."
                )
        return recorded

    def _write_install(
        self,
        name: str,
        version: str,
        project: bool,
        manifest: dict[str, str],
        *,
        source: str,
        checksums: dict[str, str],
        dependencies: dict[str, str],
        copy_from: Path | None = None,
        files: dict[str, str] | None = None,
    ) -> dict[str, Any]:
        """Materialize one installed scroll directory and its receipt."""
        base = self.project_scrolls_dir if project else self.user_dir
        dest = base / name / version
        if dest.exists():
            shutil.rmtree(dest)
        if copy_from is not None:
            shutil.copytree(copy_from, dest)
        else:
            dest.mkdir(parents=True)
            for rel, content in (files or {}).items():
                (dest / rel).write_text(content, encoding="utf-8")

        receipt = {
            "name": name,
            "version": version,
            "source": source,
            "location": "project" if project else "user",
            "installed_at": datetime.now(timezone.utc).isoformat(),
            "checksums": checksums,
            "dependencies": dependencies,
            "manifest": manifest,
        }
        (dest / "install.json").write_text(
            json.dumps(receipt, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        return receipt

    def _install_local(
        self,
        name: str,
        version: str,
        manifest: dict[str, str],
        project: bool,
        dependency_tree: dict[str, str],
    ) -> dict[str, Any]:
        """Install one planned scroll from the local registry directory."""
        src = self.scrolls_root / name / version
        if not src.is_dir():
            raise ScrollError(
                f"install: registry is missing files for {name} {version} "
                f"(expected {src})"
            )
        checksums = self._verify_checksums(name, version, src)
        return self._write_install(
            name, version, project, manifest,
            source="local", checksums=checksums,
            dependencies=dependency_tree, copy_from=src,
        )

    def _install_remote(
        self,
        name: str,
        version: str,
        manifest: dict[str, str],
        project: bool,
        remote_client: Any,
        dependency_tree: dict[str, str],
    ) -> dict[str, Any]:
        """Install one planned scroll by downloading it from the remote."""
        code, resolved = remote_client.fetch_code(name, version)
        entry_name = manifest["entry"]
        manifest_text = render_manifest({**manifest, "version": resolved})
        checksums = {
            entry_name: hashlib.sha256(code.encode("utf-8")).hexdigest(),
            "scroll.toml": hashlib.sha256(
                manifest_text.encode("utf-8")).hexdigest(),
        }
        return self._write_install(
            name, resolved, project, {**manifest, "version": resolved},
            source="remote", checksums=checksums,
            dependencies=dependency_tree,
            files={entry_name: code, "scroll.toml": manifest_text},
        )

    def install(
        self,
        name: str,
        version: str | None = None,
        project: bool = False,
        remote: bool | Any = False,
    ) -> dict[str, Any]:
        """Install a scroll and its dependencies into an install directory.

        ``project=True`` installs under ``.godcode/scrolls/`` in the current
        (or given) project directory; otherwise under ``~/.godcode/scrolls/``.
        Dependencies declared in the manifest are resolved recursively, the
        local index first and then the remote registry when ``remote`` is a
        client (or True for a default client); cycles are refused with a
        clear error.  Returns the top-level install receipt.
        """
        remote_client = self._remote_client(remote)
        plan: dict[str, dict[str, Any]] = {}
        self._plan_install(
            name,
            f"=={version}" if version is not None else None,
            (),
            remote_client,
            plan,
        )
        receipts: list[dict[str, Any]] = []
        for item in plan.values():
            tree = self._dependency_tree(item["manifest"], plan)
            if item["source"] == "local":
                receipts.append(
                    self._install_local(
                        item["name"], item["version"], item["manifest"],
                        project, tree,
                    )
                )
            else:
                assert remote_client is not None  # chosen by _choose_source
                receipts.append(
                    self._install_remote(
                        item["name"], item["version"], item["manifest"],
                        project, remote_client, tree,
                    )
                )
        return receipts[-1]

    # --------------------------------------------------------- uninstall ---

    def uninstall(
        self, name: str, version: str | None = None
    ) -> list[dict[str, str]]:
        """Remove an installed scroll (one version, or every installed
        version when ``version`` is None) from both install scopes."""
        removed: list[dict[str, str]] = []
        for base, location in (
            (self.project_scrolls_dir, "project"),
            (self.user_dir, "user"),
        ):
            name_dir = base / name
            if not name_dir.is_dir():
                continue
            if version is None:
                targets = sorted(d for d in name_dir.iterdir() if d.is_dir())
            else:
                single = name_dir / version
                targets = [single] if single.is_dir() else []
            for target in targets:
                shutil.rmtree(target)
                removed.append(
                    {"name": name, "version": target.name,
                     "location": location}
                )
            if version is None and name_dir.is_dir() and not any(
                name_dir.iterdir()
            ):
                name_dir.rmdir()
        if not removed:
            raise ScrollError(
                f"uninstall: {name!r}"
                + (f" {version}" if version else "")
                + " is not installed"
            )
        return removed

    # ------------------------------------------------------------ update ---

    def _newest_available(
        self, name: str, remote_client: Any | None
    ) -> tuple[str | None, str]:
        """(newest version known anywhere, source) for ``name``."""
        best: str | None = None
        source = "local"
        entry = self.load_index().get(name)
        if entry:
            best = entry["latest"]
        if remote_client is not None:
            try:
                info, matching = remote_client.versions_satisfying(name, None)
            except ScrollError:
                matching = []
                info = {}
            if matching and (
                best is None or compare_versions(matching[0], best) > 0
            ):
                best, source = matching[0], "remote"
        return best, source

    def update(
        self,
        name: str | None = None,
        project: bool = False,
        remote: bool | Any = False,
    ) -> list[dict[str, Any]]:
        """Update one installed scroll (or all, when ``name`` is None) to the
        newest version known to the local index or the remote registry."""
        remote_client = self._remote_client(remote)
        rows = {r["name"]: r for r in self.list_installed()}
        names = [name] if name is not None else sorted(rows)
        if name is not None and name not in rows:
            raise ScrollError(f"update: {name!r} is not installed")
        results: list[dict[str, Any]] = []
        for scroll_name in names:
            installed = rows[scroll_name]["latest"]
            available, _source = self._newest_available(scroll_name,
                                                       remote_client)
            if available is not None and compare_versions(available,
                                                          installed) > 0:
                receipt = self.install(
                    scroll_name, version=available, project=project,
                    remote=remote,
                )
                results.append(
                    {"name": scroll_name, "from": installed,
                     "to": available, "source": receipt["source"]}
                )
            else:
                results.append(
                    {"name": scroll_name, "from": installed,
                     "to": installed, "up_to_date": True}
                )
        return results

    # -------------------------------------------------------------- read ---

    def _installed_versions(self, base: Path) -> dict[str, list[str]]:
        """name -> sorted installed versions found under ``base``."""
        found: dict[str, list[str]] = {}
        if not base.is_dir():
            return found
        for name_dir in sorted(base.iterdir()):
            if not name_dir.is_dir():
                continue
            for ver_dir in sorted(name_dir.iterdir()):
                if not ver_dir.is_dir():
                    continue
                if not (ver_dir / "scroll.toml").is_file():
                    continue
                try:
                    parse_semver(ver_dir.name)
                except ScrollError:
                    continue
                found.setdefault(name_dir.name, []).append(ver_dir.name)
        return found

    def list_installed(self) -> list[dict[str, Any]]:
        """Every installed scroll; project-local entries win over user ones."""
        user = self._installed_versions(self.user_dir)
        project = self._installed_versions(self.project_scrolls_dir)
        rows: list[dict[str, Any]] = []
        for name in sorted(set(user) | set(project)):
            versions = sorted(
                set(user.get(name, [])) | set(project.get(name, [])),
                key=lambda v: parse_semver(v),
            )
            rows.append(
                {
                    "name": name,
                    "versions": versions,
                    "latest": latest_version(versions),
                    "locations": sorted(
                        {
                            *(("user",) if name in user else ()),
                            *(("project",) if name in project else ()),
                        }
                    ),
                }
            )
        return rows

    def info(self, name: str) -> dict[str, Any]:
        """Manifest, published versions, and install state for ``name``."""
        index = self.load_index()
        entry = index.get(name)
        user = self._installed_versions(self.user_dir).get(name, [])
        project = self._installed_versions(self.project_scrolls_dir).get(name, [])
        installed = sorted(set(user) | set(project),
                           key=lambda v: parse_semver(v))
        return {
            "name": name,
            "published": entry["versions"] if entry else [],
            "latest": entry["latest"] if entry else None,
            "manifest": entry["manifest"] if entry else None,
            "installed": installed,
            "installed_project": sorted(project, key=lambda v: parse_semver(v)),
            "installed_user": sorted(user, key=lambda v: parse_semver(v)),
        }

    # ------------------------------------------- interpreter resolution ----

    def resolve_entry(self, name: str) -> Optional[Path]:
        """Path to the installed entry ``.god`` file for ``name``, if any.

        Project-local installs win; otherwise the latest user-global
        version wins. Returns None when the scroll is not installed.
        """
        for base in (self.project_scrolls_dir, self.user_dir):
            name_dir = base / name
            if not name_dir.is_dir():
                continue
            versions: list[str] = []
            for ver_dir in name_dir.iterdir():
                if ver_dir.is_dir() and (ver_dir / "scroll.toml").is_file():
                    try:
                        parse_semver(ver_dir.name)
                    except ScrollError:
                        continue
                    versions.append(ver_dir.name)
            if not versions:
                continue
            latest = latest_version(versions)
            scroll_dir = name_dir / latest
            try:
                manifest = read_manifest(scroll_dir / "scroll.toml")
            except ScrollError:
                continue
            entry = scroll_dir / manifest["entry"]
            if entry.is_file():
                return entry.resolve()
            # project-local dir exists but is broken: fall through to user
        return None

