"""God Code standard library, part 4: the commons.

This module holds the everyday tools a working language needs: trimming
and searching words, sorting and gathering lists, reading maps, and
rounding numbers. They are kept apart from the interpreter core so the
language's heart stays small.

Wiring
------
``register(interp)`` adds the builtins to ``interp._builtins``. Each
builtin is a plain callable ``(args, line)`` in the style of the core
builtins (arity through ``interp._arity``, plain-word GodRuntimeError
messages).

Sandbox honesty
---------------
Every rite here is pure computation: words, lists, maps, and numbers
in, new values out. They touch no files, no network, and no host
resources. They need no sandbox grant and behave the same under
``godcode run --sandbox``.
"""

from __future__ import annotations

import math
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Callable

from godcode.errors import GodRuntimeError

__all__ = ["register"]


# ------------------------------------------------------------ value helpers


def _as_word(interp, name: str, value: Any, line) -> str:
    """Take a God Code word, number, or truth as plain text.

    Lists, maps, void, rites, and contracts have no plain-text shape
    for a word tool, so they are refused with a gentle error.
    """
    from godcode.values import Symbol

    if not isinstance(value, (str, bool, int, float, Symbol)):
        raise GodRuntimeError(
            f"{name} works on words, but a {interp.type_name(value)} "
            "was offered.",
            line,
        )
    return interp.stringify(value)


def _need_list(interp, name: str, value: Any, line) -> list:
    if not isinstance(value, list):
        raise GodRuntimeError(
            f"{name} gathers a list, but a {interp.type_name(value)} "
            "was offered.",
            line,
        )
    return value


def _need_map(interp, name: str, value: Any, line) -> dict:
    if not isinstance(value, dict):
        raise GodRuntimeError(
            f"{name} reads a map, but a {interp.type_name(value)} "
            "was offered.",
            line,
        )
    return value


def _need_number(interp, name: str, value: Any, line) -> int | float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise GodRuntimeError(
            f"{name} weighs a number, but a {interp.type_name(value)} "
            "was offered.",
            line,
        )
    return value


def _need_int(interp, name: str, value: Any, line) -> int:
    number = _need_number(interp, name, value, line)
    if isinstance(number, float) and not number.is_integer():
        raise GodRuntimeError(
            f"{name} counts in whole numbers, but {interp.stringify(value)} "
            "was offered.",
            line,
        )
    return int(number)


def _sort_key(interp, name: str, value: Any, line):
    """A sortable key for one list member: numbers, words, or truths.

    Mixed kinds cannot be ordered against each other, so they are
    refused with a gentle error.
    """
    if isinstance(value, bool):
        return (2, int(value))
    if isinstance(value, (int, float)):
        return (0, value)
    if isinstance(value, str):
        return (1, value)
    raise GodRuntimeError(
        f"{name} can order numbers, words, and truths together, but "
        f"a {interp.type_name(value)} was found among them.",
        line,
    )


def _ordered(interp, name: str, values: list, line) -> list:
    """Check every member is orderable; refuse mixed kinds gently."""
    kinds = set()
    for value in values:
        if isinstance(value, bool):
            kinds.add("truth")
        elif isinstance(value, (int, float)):
            kinds.add("number")
        elif isinstance(value, str):
            kinds.add("word")
        else:
            raise GodRuntimeError(
                f"{name} can order numbers, words, and truths, but a "
                f"{interp.type_name(value)} was found among them.",
                line,
            )
    if len(kinds) > 1:
        raise GodRuntimeError(
            f"{name} cannot order a gathering of mixed kinds "
            f"({', '.join(sorted(kinds))}).",
            line,
        )
    return values


# ------------------------------------------------------------------ words


def trim(args, line, interp):
    interp._arity("TRIM", args, 1, line)
    return _as_word(interp, "TRIM", args[0], line).strip()


def replace(args, line, interp):
    interp._arity("REPLACE", args, 3, line)
    word = _as_word(interp, "REPLACE", args[0], line)
    old = _as_word(interp, "REPLACE", args[1], line)
    new = _as_word(interp, "REPLACE", args[2], line)
    if old == "":
        raise GodRuntimeError(
            "REPLACE needs something to find: an empty word hides "
            "everywhere at once.",
            line,
        )
    return word.replace(old, new)


def starts_with(args, line, interp):
    interp._arity("STARTS_WITH", args, 2, line)
    word = _as_word(interp, "STARTS_WITH", args[0], line)
    prefix = _as_word(interp, "STARTS_WITH", args[1], line)
    return word.startswith(prefix)


def ends_with(args, line, interp):
    interp._arity("ENDS_WITH", args, 2, line)
    word = _as_word(interp, "ENDS_WITH", args[0], line)
    suffix = _as_word(interp, "ENDS_WITH", args[1], line)
    return word.endswith(suffix)


def substring(args, line, interp):
    interp._arity("SUBSTRING", args, (2, 3), line)
    word = _as_word(interp, "SUBSTRING", args[0], line)
    start = _need_int(interp, "SUBSTRING", args[1], line)
    end = _need_int(interp, "SUBSTRING", args[2], line) if len(args) == 3 else len(word)
    start = max(0, min(start, len(word)))
    end = max(0, min(end, len(word)))
    return word[start:end]


def contains(args, line, interp):
    interp._arity("CONTAINS", args, 2, line)
    haystack, needle = args[0], args[1]
    if isinstance(haystack, str):
        return _as_word(interp, "CONTAINS", needle, line) in haystack
    if isinstance(haystack, list):
        return any(item == needle for item in haystack)
    raise GodRuntimeError(
        "CONTAINS searches a word or a list, but a "
        f"{interp.type_name(haystack)} was offered.",
        line,
    )


def count(args, line, interp):
    interp._arity("COUNT", args, 2, line)
    word = _as_word(interp, "COUNT", args[0], line)
    part = _as_word(interp, "COUNT", args[1], line)
    if part == "":
        raise GodRuntimeError(
            "COUNT needs something to count: an empty word hides "
            "everywhere at once.",
            line,
        )
    return word.count(part)


def repeat(args, line, interp):
    interp._arity("REPEAT", args, 2, line)
    word = _as_word(interp, "REPEAT", args[0], line)
    times = _need_int(interp, "REPEAT", args[1], line)
    if times < 0:
        raise GodRuntimeError(
            "REPEAT counts from zero upward: a negative count was offered.",
            line,
        )
    return word * times


# ------------------------------------------------------------------ lists


def sort_list(args, line, interp):
    interp._arity("SORT", args, 1, line)
    values = _ordered(interp, "SORT", _need_list(interp, "SORT", args[0], line), line)
    return sorted(values, key=lambda v: _sort_key(interp, "SORT", v, line)[1:])


def min_of(args, line, interp):
    interp._arity("MIN_OF", args, 1, line)
    values = _ordered(interp, "MIN_OF", _need_list(interp, "MIN_OF", args[0], line), line)
    if not values:
        raise GodRuntimeError(
            "MIN_OF found an empty gathering: there is no least among nothing.",
            line,
        )
    return min(values, key=lambda v: _sort_key(interp, "MIN_OF", v, line)[1:])


def max_of(args, line, interp):
    interp._arity("MAX_OF", args, 1, line)
    values = _ordered(interp, "MAX_OF", _need_list(interp, "MAX_OF", args[0], line), line)
    if not values:
        raise GodRuntimeError(
            "MAX_OF found an empty gathering: there is no greatest among nothing.",
            line,
        )
    return max(values, key=lambda v: _sort_key(interp, "MAX_OF", v, line)[1:])


def sum_of(args, line, interp):
    interp._arity("SUM_OF", args, 1, line)
    values = _need_list(interp, "SUM_OF", args[0], line)
    total: int | float = 0
    for value in values:
        number = _need_number(interp, "SUM_OF", value, line)
        total += number
    return total


def first(args, line, interp):
    interp._arity("FIRST", args, 1, line)
    values = _need_list(interp, "FIRST", args[0], line)
    if not values:
        raise GodRuntimeError(
            "FIRST found an empty gathering: nothing stands at its head.",
            line,
        )
    return values[0]


def last(args, line, interp):
    interp._arity("LAST", args, 1, line)
    values = _need_list(interp, "LAST", args[0], line)
    if not values:
        raise GodRuntimeError(
            "LAST found an empty gathering: nothing stands at its end.",
            line,
        )
    return values[-1]


def unique(args, line, interp):
    interp._arity("UNIQUE", args, 1, line)
    values = _need_list(interp, "UNIQUE", args[0], line)
    seen: list = []
    for value in values:
        if not any(value == other for other in seen):
            seen.append(value)
    return seen


def index_of(args, line, interp):
    interp._arity("INDEX_OF", args, 2, line)
    values = _need_list(interp, "INDEX_OF", args[0], line)
    for position, value in enumerate(values):
        if value == args[1]:
            return position
    return -1


# ------------------------------------------------------------------- maps


def keys(args, line, interp):
    interp._arity("KEYS", args, 1, line)
    return list(_need_map(interp, "KEYS", args[0], line).keys())


def values_of(args, line, interp):
    interp._arity("VALUES", args, 1, line)
    return list(_need_map(interp, "VALUES", args[0], line).values())


def has_key(args, line, interp):
    interp._arity("HAS_KEY", args, 2, line)
    mapping = _need_map(interp, "HAS_KEY", args[0], line)
    key = args[1]
    if not isinstance(key, str):
        raise GodRuntimeError(
            "HAS_KEY looks up a word, but a "
            f"{interp.type_name(key)} was offered as the key.",
            line,
        )
    return str(key) in mapping


def merge(args, line, interp):
    interp._arity("MERGE", args, 2, line)
    first_map = _need_map(interp, "MERGE", args[0], line)
    second_map = _need_map(interp, "MERGE", args[1], line)
    merged = dict(first_map)
    merged.update(second_map)
    return merged


# ---------------------------------------------------------------- numbers


def absolute(args, line, interp):
    interp._arity("ABS", args, 1, line)
    return abs(_need_number(interp, "ABS", args[0], line))


def round_number(args, line, interp):
    interp._arity("ROUND", args, (1, 2), line)
    number = _need_number(interp, "ROUND", args[0], line)
    places = _need_int(interp, "ROUND", args[1], line) if len(args) == 2 else 0
    if places < 0:
        raise GodRuntimeError(
            "ROUND counts places from zero upward: a negative count "
            "was offered.",
            line,
        )
    rounded = Decimal(str(number)).quantize(
        Decimal(1).scaleb(-places), rounding=ROUND_HALF_UP
    )
    if places == 0:
        return int(rounded)
    return float(rounded)


def floor_number(args, line, interp):
    interp._arity("FLOOR", args, 1, line)
    return math.floor(_need_number(interp, "FLOOR", args[0], line))


def ceil_number(args, line, interp):
    interp._arity("CEIL", args, 1, line)
    return math.ceil(_need_number(interp, "CEIL", args[0], line))


def sqrt_number(args, line, interp):
    interp._arity("SQRT", args, 1, line)
    number = _need_number(interp, "SQRT", args[0], line)
    if number < 0:
        raise GodRuntimeError(
            "SQRT cannot root a negative number: no real answer lives there.",
            line,
        )
    rooted = math.sqrt(number)
    if float(rooted).is_integer():
        return int(rooted)
    return rooted


def power(args, line, interp):
    interp._arity("POW", args, 2, line)
    base = _need_number(interp, "POW", args[0], line)
    exp = _need_number(interp, "POW", args[1], line)
    try:
        result = math.pow(base, exp)
    except (ValueError, OverflowError):
        raise GodRuntimeError(
            "POW cannot raise that pair: the answer leaves the real numbers.",
            line,
        ) from None
    if float(result).is_integer() and abs(result) < 1e15:
        return int(result)
    return result


# ---------------------------------------------------------------- wiring


def register(interp) -> dict[str, Callable[..., Any]]:
    """Add the commons builtins to ``interp._builtins``; return them."""
    names_funcs = [
        ("TRIM", trim),
        ("REPLACE", replace),
        ("STARTS_WITH", starts_with),
        ("ENDS_WITH", ends_with),
        ("SUBSTRING", substring),
        ("CONTAINS", contains),
        ("COUNT", count),
        ("REPEAT", repeat),
        ("SORT", sort_list),
        ("MIN_OF", min_of),
        ("MAX_OF", max_of),
        ("SUM_OF", sum_of),
        ("FIRST", first),
        ("LAST", last),
        ("UNIQUE", unique),
        ("INDEX_OF", index_of),
        ("KEYS", keys),
        ("VALUES", values_of),
        ("HAS_KEY", has_key),
        ("MERGE", merge),
        ("ABS", absolute),
        ("ROUND", round_number),
        ("FLOOR", floor_number),
        ("CEIL", ceil_number),
        ("SQRT", sqrt_number),
        ("POW", power),
    ]
    builtins: dict[str, Callable[..., Any]] = {}
    for name, func in names_funcs:

        def _builtin(args, line, _func=func):
            return _func(args, line, interp)

        builtins[name] = _builtin
    interp._builtins.update(builtins)
    return builtins

files.godcode/stdlib_hashes.py:
"""God Code standard library, part 3: the scrollhouse of hashes and veils.

This module holds builtins that fingerprint and seal words: SHA-256
digests, HMAC-SHA-256 signatures, and the veils of base64. They are kept
apart from the interpreter core so the language's heart stays small.

Wiring
------
``register(interp)`` adds the builtins to ``interp._builtins``. Each
builtin is a plain callable ``(args, line)`` in the style of the core
builtins (arity through ``interp._arity``, plain-word GodRuntimeError
messages).

Sandbox honesty
---------------
SHA256, HMAC, BASE64_ENCODE, and BASE64_DECODE are pure computation:
they touch no files, no network, and no host resources. They need no
sandbox grant and behave the same under ``godcode run --sandbox``.
"""

from __future__ import annotations

import base64
import hashlib
import hmac
from typing import Any, Callable

from godcode.errors import GodRuntimeError

__all__ = ["register"]


# ------------------------------------------------------------ value helpers


def _as_text(interp, name: str, value: Any, line) -> str:
    """Take a God Code word, number, or truth as plain text.

    Lists, maps, void, rites, and contracts have no plain-text shape
    for a fingerprint, so they are refused with a gentle error.
    """
    from godcode.values import Symbol

    if not isinstance(value, (str, bool, int, float, Symbol)):
        raise GodRuntimeError(
            f"{name} can fingerprint a word, a number, or a truth, "
            f"but a {interp.type_name(value)} was offered.",
            line,
        )
    return interp.stringify(value)


def sha256(args, line, interp):
    interp._arity("SHA256", args, 1, line)
    text = _as_text(interp, "SHA256", args[0], line)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def hmac_sha256(args, line, interp):
    interp._arity("HMAC", args, 2, line)
    key = _as_text(interp, "HMAC", args[0], line)
    message = _as_text(interp, "HMAC", args[1], line)
    digest = hmac.new(
        key.encode("utf-8"), message.encode("utf-8"), hashlib.sha256
    )
    return digest.hexdigest()


def base64_encode(args, line, interp):
    interp._arity("BASE64_ENCODE", args, 1, line)
    text = _as_text(interp, "BASE64_ENCODE", args[0], line)
    return base64.b64encode(text.encode("utf-8")).decode("ascii")


def base64_decode(args, line, interp):
    interp._arity("BASE64_DECODE", args, 1, line)
    value = args[0]
    from godcode.values import Symbol

    if not isinstance(value, (str, Symbol)):
        raise GodRuntimeError(
            "BASE64_DECODE needs a veiled word to lift, "
            f"but a {interp.type_name(value)} was offered.",
            line,
        )
    veiled = str(value)
    try:
        raw = base64.b64decode(veiled, validate=True)
        return raw.decode("utf-8")
    except (ValueError, UnicodeDecodeError):
        raise GodRuntimeError(
            "BASE64_DECODE met a veil it cannot lift: the word is not "
            "well-formed base64.",
            line,
        ) from None


def register(interp) -> dict[str, Callable[..., Any]]:
    """Add the hash builtins to ``interp._builtins``; return them."""
    arity = interp._arity

    def _sha256(args, line):
        return sha256(args, line, interp)

    def _hmac(args, line):
        return hmac_sha256(args, line, interp)

    def _b64e(args, line):
        return base64_encode(args, line, interp)

    def _b64d(args, line):
        return base64_decode(args, line, interp)

    builtins: dict[str, Callable[..., Any]] = {
        "SHA256": _sha256,
        "HMAC": _hmac,
        "BASE64_ENCODE": _b64e,
        "BASE64_DECODE": _b64d,
    }
    interp._builtins.update(builtins)
    return builtins

files.godcode/stdlib_vault.py:
"""God Code standard library, part 1: the vault of JSON and the filesystem.

This module holds builtins that read and write the outer world: parsing
and rendering JSON, and reading, writing, and listing files. It is kept
apart from the interpreter core so the language's heart stays small.

Wiring
------
``register(interp)`` adds the builtins to ``interp._builtins``. Each
builtin is a plain callable ``(args, line)`` in the style of the core
builtins (arity through ``interp._arity``, plain-word GodRuntimeError
messages).

Sandbox honesty
---------------
READ_FILE, WRITE_FILE, LIST_DIR, and FILE_EXISTS reach the host
filesystem. When the interpreter runs under ``godcode.sandbox``, the
sandbox guard (``interp._sandbox_guard``, installed by
``Sandbox.install``) carries the policy, and these builtins honor it:

* writes are refused unless the policy grants ``allow_write``;
* reads are refused unless the policy grants ``allow_read_paths``,
  and then only under one of the granted directories.

JSON_PARSE and JSON_STRING are pure and need no grant.
"""

from __future__ import annotations

import json
import os
from typing import Any, Callable

from godcode.errors import GodRuntimeError, SandboxViolation
from godcode.values import Contract, RiteFunction, Symbol

__all__ = ["register"]


# ------------------------------------------------------------ value helpers


def _as_word(interp, name: str, value: Any, line) -> str:
    """Take a God Code word as plain text. Symbols give up their text."""
    if isinstance(value, Symbol):
        return str(value)
    if isinstance(value, str):
        return value
    raise GodRuntimeError(
        f"{name} needs a word, but a {interp.type_name(value)} was offered.",
        line,
    )


def _from_json(value: Any) -> Any:
    """Turn a json.loads result into God Code values.

    Objects become maps, arrays become lists, null becomes void.
    Numbers, words, and booleans cross over unchanged.
    """
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, list):
        return [_from_json(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _from_json(item) for key, item in value.items()}
    raise GodRuntimeError(f"JSON_PARSE met a value it cannot carry: {value!r}.")


def _to_json_text(interp, value: Any, line) -> str:
    """Render a God Code value as compact JSON.

    Raises a plain GodRuntimeError for values JSON cannot carry:
    rites, contracts, symbols, non-word map keys, and numbers with no
    JSON shape (infinity, not-a-number).
    """
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, Symbol):
        raise GodRuntimeError(
            "JSON_STRING cannot carry a symbol. "
            "Only words, numbers, booleans, lists, and maps have a JSON shape.",
            line,
        )
    if isinstance(value, str):
        return json.dumps(value)
    if isinstance(value, (int, float)):
        try:
            return json.dumps(value, allow_nan=False)
        except ValueError:
            raise GodRuntimeError(
                "JSON_STRING cannot carry a number with no JSON shape, "
                "like infinity or not-a-number.",
                line,
            ) from None
    if isinstance(value, list):
        inner = ",".join(_to_json_text(interp, item, line) for item in value)
        return "[" + inner + "]"
    if isinstance(value, dict):
        parts = []
        for key, item in value.items():
            if isinstance(key, Symbol) or not isinstance(key, str):
                raise GodRuntimeError(
                    "JSON_STRING needs map keys that are words. "
                    f"A {interp.type_name(key)} key was found.",
                    line,
                )
            parts.append(json.dumps(key) + ":" + _to_json_text(interp, item, line))
        return "{" + ",".join(parts) + "}"
    if isinstance(value, RiteFunction):
        raise GodRuntimeError(
            "JSON_STRING cannot carry a rite. Rites have no JSON shape.",
            line,
        )
    if isinstance(value, Contract):
        raise GodRuntimeError(
            "JSON_STRING cannot carry a contract. Contracts have no JSON shape.",
            line,
        )
    raise GodRuntimeError(
        f"JSON_STRING cannot carry {interp.type_name(value)}. "
        "Only words, numbers, booleans, lists, and maps have a JSON shape.",
        line,
    )


# ------------------------------------------------------------ sandbox guard


def _guard(interp):
    """The sandbox guard, if this interpreter runs under godcode.sandbox."""
    return getattr(interp, "_sandbox_guard", None)


def _check_read_grant(interp, rite: str, path: str, line) -> None:
    """Refuse filesystem reads the sandbox policy does not grant.

    No guard means no sandbox: the read proceeds. Under a guard, reads
    need ``allow_read_paths``, and the resolved path must lie under one
    of the granted directories (the same rule the sandbox applies to
    scroll imports).
    """
    guard = _guard(interp)
    if guard is None:
        return
    allowed = guard.policy.allow_read_paths
    if not allowed:
        raise SandboxViolation(
            f"The sandbox withholds this power: the rite {rite} would read "
            "from the outer world. It is not granted.",
            line,
        )
    resolved = os.path.realpath(path)
    for base in allowed:
        base_resolved = os.path.realpath(base)
        # A grant on the filesystem root blesses everything, as in a
        # plain `godcode run` with no guard installed.
        if base_resolved == os.path.realpath(os.sep):
            _check_manifest_path(interp, "read", rite, path, line)
            return
        if resolved == base_resolved or resolved.startswith(base_resolved + os.sep):
            _check_manifest_path(interp, "read", rite, path, line)
            return
    raise SandboxViolation(
        f"The sandbox withholds this power: the rite {rite} may not read "
        f"'{path}'. It lies outside the granted paths.",
        line,
    )


def _check_manifest_path(interp, kind: str, rite: str, path: str, line) -> None:
    """Refuse filesystem access the scroll's permission manifest withholds.

    The guard's own ``check_rite`` already polices the call through the
    interpreter's dispatch; the vault reaches the filesystem directly, so
    it applies the manifest's target rule here as well.
    """
    manifest = getattr(interp, "manifest", None)
    if not manifest:
        return
    # The manifest holds absolute prefixes; realpath() resolves the
    # runtime target exactly the way open() will, so the check mirrors
    # the file the rite is about to touch.
    allowed = (
        manifest.allows_read(path) if kind == "read"
        else manifest.allows_write(path)
    )
    if not allowed:
        raise SandboxViolation(
            f"The scroll reaches for a power it did not declare: the rite "
            f"{rite} may not touch '{path}'. Declare it at the top of the "
            f"scroll with DECLARE PERMISSION TO, or leave the power "
            f"untouched.",
            line,
        )


def _check_write_grant(interp, path: str, line) -> None:
    """Refuse filesystem writes the sandbox policy does not grant."""
    guard = _guard(interp)
    if guard is None:
        return
    if not guard.policy.allow_write:
        raise SandboxViolation(
            "The sandbox withholds this power: the rite WRITE_FILE would "
            f"write '{path}' to the outer world. It is not granted.",
            line,
        )
    _check_manifest_path(interp, "write", "WRITE_FILE", path, line)


# ------------------------------------------------------------------ register


def register(interp) -> None:
    """Add the vault builtins to ``interp._builtins``.

    Idempotent: calling it twice simply replaces the same six entries.
    """
    arity = interp._arity

    def json_parse(args, line):
        arity("JSON_PARSE", args, 1, line)
        text = _as_word(interp, "JSON_PARSE", args[0], line)
        try:
            return _from_json(json.loads(text))
        except json.JSONDecodeError as exc:
            raise GodRuntimeError(
                f"JSON_PARSE could not read that word as JSON. {exc.msg}: "
                f"line {exc.lineno} column {exc.colno}.",
                line,
            ) from None

    def json_string(args, line):
        arity("JSON_STRING", args, 1, line)
        return _to_json_text(interp, args[0], line)

    def read_file(args, line):
        arity("READ_FILE", args, 1, line)
        path = _as_word(interp, "READ_FILE", args[0], line)
        _check_read_grant(interp, "READ_FILE", path, line)
        try:
            with open(path, "r", encoding="utf-8") as handle:
                return handle.read()
        except OSError as exc:
            raise GodRuntimeError(
                f"READ_FILE could not read '{path}'. {exc.strerror or exc}.",
                line,
            ) from None

    def write_file(args, line):
        arity("WRITE_FILE", args, 2, line)
        path = _as_word(interp, "WRITE_FILE", args[0], line)
        text = _as_word(interp, "WRITE_FILE", args[1], line)
        _check_write_grant(interp, path, line)
        try:
            with open(path, "w", encoding="utf-8") as handle:
                return handle.write(text)
        except OSError as exc:
            raise GodRuntimeError(
                f"WRITE_FILE could not write '{path}'. {exc.strerror or exc}.",
                line,
            ) from None

    def file_exists(args, line):
        arity("FILE_EXISTS", args, 1, line)
        path = _as_word(interp, "FILE_EXISTS", args[0], line)
        _check_read_grant(interp, "FILE_EXISTS", path, line)
        return os.path.exists(path)

    def list_dir(args, line):
        arity("LIST_DIR", args, 1, line)
        path = _as_word(interp, "LIST_DIR", args[0], line)
        _check_read_grant(interp, "LIST_DIR", path, line)
        if not os.path.isdir(path):
            raise GodRuntimeError(
                f"LIST_DIR needs a directory, but '{path}' is not one.",
                line,
            )
        try:
            entries = os.listdir(path)
        except OSError as exc:
            raise GodRuntimeError(
                f"LIST_DIR could not open '{path}'. {exc.strerror or exc}.",
                line,
            ) from None
        return sorted(str(entry) for entry in entries)

    builtins: dict[str, Callable[..., Any]] = {
        "JSON_PARSE": json_parse,
        "JSON_STRING": json_string,
        "READ_FILE": read_file,
        "WRITE_FILE": write_file,
        "FILE_EXISTS": file_exists,
        "LIST_DIR": list_dir,
    }
    interp._builtins.update(builtins)

files.godcode/tester.py:
"""The God Code test runner, behind `godcode test`.

Convention: a *test scroll* is any `.god` file named `test_*.god` or
`*_test.god`. Inside it, every rite named `TEST_*` (case-insensitive) is
one test case. The scroll is parsed once; then each `TEST_*` rite runs in
a FRESH `Interpreter`, so tests cannot leak state into each other. A
`TESTIFY` failure fails that test, and any runtime error fails it too,
with the error message carried in the report.

Discovery reads only the given directory itself; subfolders are not
entered. The runner binds no Spirit, no covenant ledger, and no audit log
(`log_path=None`), and it runs scrolls the same way `godcode run` does
(not sandboxed): only test scrolls you wrote or trust.
"""

from __future__ import annotations

import contextlib
import io
from dataclasses import dataclass, field
from pathlib import Path

from godcode.ast import CreationBlock, DefineRite
from godcode.errors import GodCodeError
from godcode.interpreter import Interpreter
from godcode.tongues import parse_source
from godcode.values import RiteFunction

#: Rite label used when the failure belongs to the scroll itself (it could
#: not be read or parsed), not to any single rite.
SCROLL_LEVEL = "(scroll)"


# ---------------------------------------------------------------------------
# results
# ---------------------------------------------------------------------------
@dataclass
class TestResult:
    """One test's outcome. `ok` is True (passed), False (failed), or None
    (skipped, e.g. the rite asks for offerings)."""

    file: str
    rite: str
    ok: bool | None
    message: str = ""


@dataclass
class TestReport:
    results: list[TestResult] = field(default_factory=list)
    #: Names of test scrolls that held no TEST_ rites at all.
    empty_files: list[str] = field(default_factory=list)

    @property
    def passed(self) -> int:
        return sum(1 for r in self.results if r.ok is True)

    @property
    def failed(self) -> int:
        return sum(1 for r in self.results if r.ok is False)

    @property
    def skipped(self) -> int:
        return sum(1 for r in self.results if r.ok is None)

    def text_lines(self) -> list[str]:
        """Human report: one line per test, then the summary line."""
        lines = []
        for r in self.results:
            status = "PASS" if r.ok is True else ("SKIP" if r.ok is None else "FAIL")
            line = f"{status}  {r.file} :: {r.rite}"
            if r.message:
                line += f" :: {r.message}"
            lines.append(line)
        for name in self.empty_files:
            lines.append(f"{name} :: no TEST_ rites found.")
        parts = [f"{self.passed} passed", f"{self.failed} failed"]
        if self.skipped:
            parts.append(f"{self.skipped} skipped")
        lines.append(", ".join(parts) + ".")
        return lines

    def payload(self, dir_label: str) -> dict:
        """Machine report for `godcode test --json`."""
        return {
            "tool": "godcode",
            "command": "test",
            "dir": dir_label,
            "tests": [
                {"file": r.file, "rite": r.rite, "ok": r.ok, "message": r.message}
                for r in self.results
            ],
            "passed": self.passed,
            "failed": self.failed,
            "skipped": self.skipped,
        }


# ---------------------------------------------------------------------------
# discovery
# ---------------------------------------------------------------------------
def is_test_file(name: str) -> bool:
    """True for `test_*.god` and `*_test.god` (case-insensitive)."""
    lowered = name.lower()
    return lowered.endswith(".god") and (
        lowered.startswith("test_") or lowered[:-4].endswith("_test")
    )


def discover_test_files(directory: Path) -> list[Path]:
    """Test scrolls in `directory`, sorted by name. Non-recursive: only the
    directory itself is read, subfolders are not entered."""
    return sorted(
        (p for p in directory.iterdir() if p.is_file() and is_test_file(p.name)),
        key=lambda p: p.name,
    )


# ---------------------------------------------------------------------------
# collection
# ---------------------------------------------------------------------------
def _top_level_statements(program) -> list:
    stmts = getattr(program, "statements", None) or []
    if len(stmts) == 1 and isinstance(stmts[0], CreationBlock):
        return stmts[0].statements
    return stmts


def collect_test_rites(program) -> list[DefineRite]:
    """The `TEST_*` rites defined at the scroll's top level, in definition
    order. A repeated name keeps its first position but the last definition
    wins when the rite runs (as `DECLARE` would)."""
    found: dict[str, DefineRite] = {}
    for stmt in _top_level_statements(program):
        if isinstance(stmt, DefineRite) and stmt.name.upper().startswith("TEST_"):
            found[stmt.name] = stmt
    return list(found.values())


# ---------------------------------------------------------------------------
# execution
# ---------------------------------------------------------------------------
def _parse_scroll(path: Path):
    source = path.read_text(encoding="utf-8")
    return parse_source(source)


def _run_rite(program, rite_node: DefineRite, file_label: str) -> TestResult:
    """Run one TEST_ rite in a fresh interpreter and report the outcome."""
    interp = Interpreter(log_path=None)
    buf = io.StringIO()
    # The runner's own report must stay one line per test: swallow REVEAL
    # lines, [TESTIFY] notices, and any other chatter the scroll makes.
    with contextlib.redirect_stdout(buf):
        try:
            interp.run(program, source_name=file_label)
        except GodCodeError as err:
            return TestResult(file_label, rite_node.name, False,
                              f"the scroll could not be prepared: {err}")
        except Exception as exc:  # an engine fault, not a test failure
            return TestResult(file_label, rite_node.name, False,
                              f"the scroll could not be prepared: "
                              f"{type(exc).__name__}: {exc}")
        target = interp.env.get(rite_node.name) \
            if interp.env.is_bound(rite_node.name) else None
        if not isinstance(target, RiteFunction):
            return TestResult(
                file_label, rite_node.name, False,
                f"the rite {rite_node.name} was not found "
                f"after the scroll ran.")
        if target.params:
            n = len(target.params)
            return TestResult(
                file_label, rite_node.name, None,
                f"the rite asks for {n} offering{'s' if n != 1 else ''}, "
                f"so it was not called.")
        try:
            interp._call_rite(target, [], rite_node.line)
        except GodCodeError as err:
            return TestResult(file_label, rite_node.name, False, str(err))
        except Exception as exc:  # an engine fault, not a test failure
            return TestResult(file_label, rite_node.name, False,
                              f"{type(exc).__name__}: {exc}")
    return TestResult(file_label, rite_node.name, True, "")


def run_test_file(path: Path) -> tuple[list[TestResult], bool]:
    """Parse `path` once, then run each TEST_ rite in isolation.

    Returns (results, is_empty). A scroll that cannot be read or parsed
    yields one file-level failure and never crashes the runner.
    """
    label = path.name
    try:
        program = _parse_scroll(path)
    except GodCodeError as err:
        return [TestResult(label, SCROLL_LEVEL, False, str(err))], False
    except OSError as exc:
        return [TestResult(
            label, SCROLL_LEVEL, False,
            f"the scroll could not be read: {exc.strerror or exc}")], False
    rites = collect_test_rites(program)
    if not rites:
        return [], True
    return [_run_rite(program, rite, label) for rite in rites], False


def run_tests(directory: Path) -> TestReport:
    """Discover test scrolls in `directory` and run them all."""
    report = TestReport()
    for path in discover_test_files(directory):
        results, is_empty = run_test_file(path)
        report.results.extend(results)
        if is_empty:
            report.empty_files.append(path.name)
    return report

